#include <iostream>
#include <string>

int main() {
    std::string s;
    std::cin >> s;

    int n = (int)s.size();

    // Find the first '['
    int left_bracket = -1;
    for (int i = 0; i < n; i++) {
        if (s[i] == '[') {
            left_bracket = i;
            break;
        }
    }
    if (left_bracket == -1) {
        std::cout << -1 << "\n";
        return 0;
    }

    // Find the last ']'
    int right_bracket = -1;
    for (int i = n - 1; i >= 0; i--) {
        if (s[i] == ']') {
            right_bracket = i;
            break;
        }
    }
    if (right_bracket == -1 || right_bracket <= left_bracket) {
        std::cout << -1 << "\n";
        return 0;
    }

    // Find the first ':' after left_bracket
    int left_colon = -1;
    for (int i = left_bracket + 1; i < right_bracket; i++) {
        if (s[i] == ':') {
            left_colon = i;
            break;
        }
    }
    if (left_colon == -1) {
        std::cout << -1 << "\n";
        return 0;
    }

    // Find the last ':' before right_bracket
    int right_colon = -1;
    for (int i = right_bracket - 1; i > left_colon; i--) {
        if (s[i] == ':') {
            right_colon = i;
            break;
        }
    }
    if (right_colon == -1 || right_colon <= left_colon) {
        std::cout << -1 << "\n";
        return 0;
    }

    // Count '|' between left_colon and right_colon
    int pipe_count = 0;
    for (int i = left_colon + 1; i < right_colon; i++) {
        if (s[i] == '|') pipe_count++;
    }

    // Length = 4 + number of '|' between colons
    std::cout << 4 + pipe_count << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>

using namespace std;

long long sum_of_digits(const string &s) {
    long long sum = 0;
    for (char c : s) sum += c - '0';
    return sum;
}

int main() {
    string x;
    cin >> x;

    long long best_sum = -1;
    string best_num = x;

    // Check x itself
    best_sum = sum_of_digits(x);

    // Try to find a better number by decreasing one digit and setting following digits to 9
    for (int i = 0; i < (int)x.size(); i++) {
        if (x[i] == '0') continue;

        string candidate = x;
        candidate[i] = (candidate[i] - '1'); // decrease this digit by 1
        for (int j = i + 1; j < (int)candidate.size(); j++) {
            candidate[j] = '9';
        }

        // Remove leading zeros if any
        int pos = 0;
        while (pos < (int)candidate.size() && candidate[pos] == '0') pos++;
        if (pos == (int)candidate.size()) continue; // all zeros, skip
        candidate = candidate.substr(pos);

        long long s = sum_of_digits(candidate);
        if (s > best_sum) {
            best_sum = s;
            best_num = candidate;
        } else if (s == best_sum) {
            // If sum equal, choose bigger number
            if (candidate.size() > best_num.size() || (candidate.size() == best_num.size() && candidate > best_num)) {
                best_num = candidate;
            }
        }
    }

    cout << best_num << "\n";

    return 0;
}

