#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t; cin >> t;
    while (t--) {
        int n;
        long long x;
        cin >> n >> x;
        vector<pair<long long, long long>> blows(n);
        for (int i = 0; i < n; i++) {
            cin >> blows[i].first >> blows[i].second;
        }

        // Check if any blow can kill immediately
        bool canKillImmediately = false;
        for (auto& b : blows) {
            if (b.first >= x) {
                canKillImmediately = true;
                break;
            }
        }
        if (canKillImmediately) {
            cout << 1 << "\n";
            continue;
        }

        // Find the maximum net damage (d_i - h_i)
        long long maxNetDamage = LLONG_MIN;
        long long maxD = 0;
        for (auto& b : blows) {
            long long net = b.first - b.second;
            if (net > maxNetDamage) maxNetDamage = net;
            if (b.first > maxD) maxD = b.first;
        }

        // If max net damage <= 0, can't reduce heads to zero
        if (maxNetDamage <= 0) {
            cout << -1 << "\n";
            continue;
        }

        // Otherwise, use the blow with max net damage repeatedly until heads <= maxD,
        // then one blow to kill
        // Number of blows = ceil((x - maxD) / maxNetDamage) + 1
        long long remaining = x - maxD;
        long long blowsNeeded = (remaining + maxNetDamage - 1) / maxNetDamage + 1;
        cout << blowsNeeded << "\n";
    }

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    unsigned long long n, m;
    cin >> n >> m;

    // If m >= n, barn is full every day before sparrows eat
    if (m >= n) {
        // We need to find the first day d such that d >= n (since barn starts full)
        // On day d, sparrows eat d grains, barn has n grains max
        // barn after sparrows = n - d
        // We want n - d <= 0 => d >= n
        cout << n << "\n";
        return 0;
    }

    // Otherwise, barn is not always full, grains accumulate
    // After day d:
    // grains = min(n, initial + d*m) - sum of sparrows = min(n, n + d*m) - d(d+1)/2
    // Since initial is n, min(n, n + d*m) = n (barn capacity)
    // So grains after day d = n - d(d+1)/2 + d*m
    // We want to find minimal d such that grains <= 0:
    // n + d*m - d(d+1)/2 <= 0
    // d(d+1)/2 - d*m >= n
    // d(d+1)/2 - d*m - n >= 0

    // Let's define f(d) = d(d+1)/2 - d*m - n
    // We want minimal d with f(d) >= 0

    // Use binary search to find minimal d
    unsigned long long left = 1, right = 2e9; // large enough upper bound
    while (left < right) {
        unsigned long long mid = left + (right - left) / 2;
        // To avoid overflow, use __int128 or careful calculation
        __int128 val = (__int128)mid * (mid + 1) / 2;
        val -= (__int128)mid * m;
        val -= n;
        if (val >= 0) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }

    cout << left << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    array<int, 27> cnt{}; // 9 numbers * 3 suits
    auto idx = [](char d, char s) {
        int base = 0;
        if (s == 'm') base = 0;
        else if (s == 'p') base = 9;
        else base = 18;
        return base + (d - '1');
    };

    for (int i = 0; i < 3; i++) {
        string t; cin >> t;
        cnt[idx(t[0], t[1])]++;
    }

    // Check if already have a mentsu (koutsu or shuntsu)
    // koutsu: any tile count >= 3
    for (int i = 0; i < 27; i++) {
        if (cnt[i] >= 3) {
            cout << 0 << "\n";
            return 0;
        }
    }
    // shuntsu: three consecutive numbers in same suit
    for (int base = 0; base < 27; base += 9) {
        for (int i = 0; i + 2 < 9; i++) {
            if (cnt[base + i] >= 1 && cnt[base + i + 1] >= 1 && cnt[base + i + 2] >= 1) {
                cout << 0 << "\n";
                return 0;
            }
        }
    }

    // If not, try to find minimal extra tiles to draw to form a mentsu
    // We can draw any tiles any number of times.

    // For koutsu:
    // For each tile, need (3 - cnt[i]) tiles to complete koutsu
    int ans = 3; // max needed is 3
    for (int i = 0; i < 27; i++) {
        int need = 3 - cnt[i];
        if (need < ans) ans = need;
    }

    // For shuntsu:
    // For each possible shuntsu (3 consecutive tiles in same suit),
    // count how many tiles missing to complete it
    for (int base = 0; base < 27; base += 9) {
        for (int i = 0; i + 2 < 9; i++) {
            int have = 0;
            if (cnt[base + i] > 0) have++;
            if (cnt[base + i + 1] > 0) have++;
            if (cnt[base + i + 2] > 0) have++;
            int need = 3 - have;
            if (need < ans) ans = need;
        }
    }

    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n; 
    cin >> n;
    string s; 
    cin >> s;

    int totalG = 0;
    for (char c : s) if (c == 'G') totalG++;

    if (totalG == 0) {
        cout << 0 << "\n";
        return 0;
    }
    if (totalG == n) {
        cout << n << "\n";
        return 0;
    }

    // left[i] = length of consecutive G ending at i
    vector<int> left(n, 0);
    if (s[0] == 'G') left[0] = 1;
    for (int i = 1; i < n; i++) {
        if (s[i] == 'G') left[i] = left[i-1] + 1;
        else left[i] = 0;
    }

    // right[i] = length of consecutive G starting at i
    vector<int> right(n, 0);
    if (s[n-1] == 'G') right[n-1] = 1;
    for (int i = n-2; i >= 0; i--) {
        if (s[i] == 'G') right[i] = right[i+1] + 1;
        else right[i] = 0;
    }

    int ans = *max_element(left.begin(), left.end()); // max segment without swap

    // Try swapping one S with one G to maximize segment
    for (int i = 0; i < n; i++) {
        if (s[i] == 'S') {
            int leftG = (i > 0) ? left[i-1] : 0;
            int rightG = (i < n-1) ? right[i+1] : 0;
            int combined = leftG + rightG;

            // If totalG > combined, we can swap to get combined+1
            // else combined (no extra G to swap)
            int candidate = (combined < totalG) ? combined + 1 : combined;
            ans = max(ans, candidate);
        }
    }

    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> p(k);
    vector<bool> used(n + 1, false);
    for (int i = 0; i < k; i++) {
        cin >> p[i];
        used[p[i]] = true;
    }

    // Check if the given prefix is stack-sortable by simulating the stack sorting process
    // If not stack-sortable, print -1 immediately
    {
        stack<int> s;
        int cur = 1;
        for (int i = 0; i < k; i++) {
            int x = p[i];
            while (cur <= x) {
                s.push(cur++);
            }
            if (s.top() != x) {
                cout << -1 << "\n";
                return 0;
            }
            s.pop();
        }
    }

    // We want to restore the remaining n-k elements to get a lex max stack-sortable permutation
    // The known fact: a permutation is stack-sortable iff it avoids the pattern 231
    // The problem reduces to:
    // - The first k elements are fixed and stack-sortable prefix
    // - We must append the remaining elements (not used in prefix) in some order to get a full stack-sortable permutation
    // - Among all such completions, choose lex max

    // The approach:
    // We simulate the stack sorting process for the prefix to find the current stack state after prefix
    // Then we append the remaining elements in decreasing order, but we must ensure the final permutation is stack-sortable
    // The stack after prefix simulation is the key to decide the order of remaining elements

    // Let's simulate the prefix again and record the stack after processing prefix
    stack<int> s;
    int cur = 1;
    for (int i = 0; i < k; i++) {
        int x = p[i];
        while (cur <= x) {
            s.push(cur++);
        }
        s.pop();
    }

    // The remaining elements are those not used in prefix
    vector<int> rem;
    for (int i = 1; i <= n; i++) {
        if (!used[i]) rem.push_back(i);
    }
    // We want to append rem elements to p to get lex max permutation
    // The lex max means we want to put the largest possible element earliest in the suffix

    // The key insight from editorial and known results:
    // The stack after prefix simulation is the current stack state
    // The next elements must be appended in an order that does not break stack-sortability
    // The stack is strictly decreasing (top is smallest)
    // To keep stack-sortable, the next elements must be inserted so that the stack remains decreasing

    // So we must insert the remaining elements in an order that respects the stack order:
    // The next element to push must be smaller than the top of the stack or we must pop from stack first

    // We will reconstruct the suffix by simulating the stack sorting process:
    // We have:
    // - s: current stack after prefix
    // - rem: remaining elements to place in p (not used in prefix)
    // We want to find an order of rem to append to p so that the full permutation is stack-sortable
    // and lex max.

    // The approach:
    // We will build the suffix from left to right.
    // At each step, we can either:
    // - push next element from rem into stack
    // - pop from stack to output (which corresponds to next element in p)
    // But we only control the order of rem elements in p (the suffix)
    // So the suffix is the order in which we push elements from rem into the stack.

    // The problem reduces to:
    // Find an order of rem elements to append to p so that the full permutation is stack-sortable,
    // and lex max.

    // The known characterization of stack-sortable permutations:
    // The permutation is stack-sortable iff it avoids 231 pattern.
    // The stack after prefix simulation is strictly decreasing.
    // To keep stack-sortable, the suffix must be such that when merged with the stack,
    // the output is sorted.

    // The editorial approach (from known solutions):
    // The suffix must be a decreasing sequence that fits into the stack without violating the order.
    // So the suffix must be strictly decreasing and each element must be less than the top of the stack
    // or we must pop from stack first.

    // Since we want lex max suffix, we try to put the largest possible elements first,
    // but we must ensure that the suffix is strictly decreasing and each element is less than the top of the stack.

    // Let's implement a greedy approach:
    // We will try to build the suffix in decreasing order.
    // We will maintain a stack representing the current stack after prefix.
    // For each element in rem sorted descending:
    //   - If stack is empty or top of stack > element, we can push element into stack (append element to suffix)
    //   - Else, we cannot push element now, so we must pop from stack first (which means suffix is invalid)
    // If at any point we cannot push element, no solution.

    // But we must produce the suffix array (the order of rem elements in p)
    // So we try to build suffix by pushing elements in descending order if possible.

    // Let's implement this logic:

    // Sort rem descending
    sort(rem.rbegin(), rem.rend());

    vector<int> suffix;
    // We'll simulate the stack after prefix, but we need to check if we can push elements in rem order
    // The stack after prefix is s, but we cannot modify s directly because we need to check feasibility
    // Let's copy s to a vector for easier manipulation
    vector<int> stk;
    while (!s.empty()) {
        stk.push_back(s.top());
        s.pop();
    }
    reverse(stk.begin(), stk.end()); // bottom to top order

    // We'll simulate pushing elements from rem into stack stk
    // The stack must remain strictly decreasing from bottom to top
    // So top element is smallest

    // We'll try to push elements from rem in descending order
    // For each element x in rem:
    //   - If stk empty or stk.back() > x, push x
    //   - else no solution

    for (int x : rem) {
        if (stk.empty() || stk.back() > x) {
            stk.push_back(x);
            suffix.push_back(x);
        } else {
            // no solution
            cout << -1 << "\n";
            return 0;
        }
    }

    // Now suffix is the order of appended elements
    // The full permutation is p + suffix
    // This permutation is stack-sortable and lex max

    for (int x : p) cout << x << " ";
    for (int x : suffix) cout << x << " ";
    cout << "\n";

    return 0;
}

