#include <iostream>
using namespace std;

int main() {
    long long cnt1, cnt2, cnt3, cnt4;
    cin >> cnt1 >> cnt2 >> cnt3 >> cnt4;

    // Total number of '(' and ')' must be equal
    // '(' count = 2*cnt1 + cnt2 + cnt3
    // ')' count = cnt2 + cnt3 + 2*cnt4
    // So, 2*cnt1 + cnt2 + cnt3 == cnt2 + cnt3 + 2*cnt4
    // => 2*cnt1 == 2*cnt4
    // => cnt1 == cnt4

    if (cnt1 != cnt4) {
        cout << 0 << "\n";
        return 0;
    }

    // Now check if we can arrange the strings to form a regular bracket sequence.
    // The key is that the number of ")(" strings (cnt3) cannot exceed the number of "()"
    // strings (cnt2) by more than 1, otherwise the sequence cannot be balanced properly.
    // This is a known condition from the problem editorial.

    if (cnt3 > cnt2 + 1) {
        cout << 0 << "\n";
        return 0;
    }

    cout << 1 << "\n";
    return 0;
}

