#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s; cin >> s;
    int n = (int)s.size();

    // Precompute the minimal character from position i to end in s
    vector<char> min_suf(n+1, '{'); // '{' > 'z'
    for (int i = n-1; i >= 0; i--) {
        min_suf[i] = min(s[i], min_suf[i+1]);
    }

    string t, u;
    int i = 0;
    while (i < n || !t.empty()) {
        if (t.empty()) {
            t.push_back(s[i++]);
        } else {
            // If we can still take from s and s[i] <= min character in t, take from s
            if (i < n && s[i] <= *min_element(t.begin(), t.end())) {
                t.push_back(s[i++]);
            } else {
                // Otherwise, pop from t to u
                u.push_back(t.back());
                t.pop_back();
            }
        }
    }

    cout << u << "\n";
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T; cin >> T;
    while (T--) {
        int n; cin >> n;
        int prev_p = 0, prev_c = 0;
        bool valid = true;
        for (int i = 0; i < n; i++) {
            int p, c; cin >> p >> c;
            if (p < prev_p) valid = false;          // plays can't decrease
            if (c < prev_c) valid = false;          // clears can't decrease
            if (c > p) valid = false;                // clears can't be more than plays
            if ((p - prev_p) < (c - prev_c)) valid = false; // new clears can't exceed new plays
            prev_p = p;
            prev_c = c;
        }
        cout << (valid ? "YES\n" : "NO\n");
    }

    return 0;
}

#include <iostream>
