bool isPalindrome(int h, int m) {
    // Format time as hh:mm
    char time[6];
    sprintf(time, "%02d:%02d", h, m);
    // Check palindrome ignoring ':'
    return (time[0] == time[4]) && (time[1] == time[3]);
}

int main() {
    string s;
    cin >> s;
    int h = stoi(s.substr(0, 2));
    int m = stoi(s.substr(3, 2));

