#include <bits/stdc++.h>
using namespace std;

string a, b;
int n;
int cnt[10];
string ans;
bool found = false;

void dfs(int pos, bool limit, bool lead, string &cur) {
    if (pos == n) {
        ans = cur;
        found = true;
        return;
    }
    int up = limit ? (b[pos] - '0') : 9;
    for (int d = up; d >= 0; d--) {
        if (cnt[d] == 0) continue;
        if (pos == 0 && d == 0) continue; // no leading zero
        cnt[d]--;
        cur.push_back(d + '0');
        dfs(pos + 1, limit && (d == up), false, cur);
        if (found) return;
        cur.pop_back();
        cnt[d]++;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> a >> b;
    n = (int)a.size();

    // If length of a < length of b, just sort descending and print
    if ((int)a.size() < (int)b.size()) {
        sort(a.rbegin(), a.rend());
        cout << a << "\n";
        return 0;
    }

    // length equal
    memset(cnt, 0, sizeof(cnt));
    for (char c : a) cnt[c - '0']++;

    string cur;
    dfs(0, true, true, cur);
    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

const int N = 10;
const int dx[4] = {1, 0, 1, 1};
const int dy[4] = {0, 1, 1, -1};

bool checkWin(const vector<string>& board, int x, int y) {
    for (int dir = 0; dir < 4; dir++) {
        int count = 1;
        // check forward direction
        int nx = x + dx[dir], ny = y + dy[dir];
        while (nx >= 0 && nx < N && ny >= 0 && ny < N && board[ny][nx] == 'X') {
            count++;
            nx += dx[dir];
            ny += dy[dir];
        }
        // check backward direction
        nx = x - dx[dir];
        ny = y - dy[dir];
        while (nx >= 0 && nx < N && ny >= 0 && ny < N && board[ny][nx] == 'X') {
            count++;
            nx -= dx[dir];
            ny -= dy[dir];
        }
        if (count >= 5) return true;
    }
    return false;
}

int main() {
    vector<string> board(N);
    for (int i = 0; i < N; i++) {
        cin >> board[i];
    }

    for (int y = 0; y < N; y++) {
        for (int x = 0; x < N; x++) {
            if (board[y][x] == '.') {
                board[y][x] = 'X';
                if (checkWin(board, x, y)) {
                    cout << "YES\n";
                    return 0;
                }
                board[y][x] = '.';
            }
        }
    }
    cout << "NO\n";
    return 0;
}

