#include <iostream>
#include <vector>
#include <set>
using namespace std;

bool checkHorizontal(const vector<string>& flag, int n, int m) {
    if (n % 3 != 0) return false;
    int stripeHeight = n / 3;
    set<char> colors;
    for (int i = 0; i < 3; ++i) {
        char c = flag[i * stripeHeight][0];
        colors.insert(c);
        for (int r = i * stripeHeight; r < (i + 1) * stripeHeight; ++r) {
            for (int col = 0; col < m; ++col) {
                if (flag[r][col] != c) return false;
            }
        }
    }
    return colors.size() == 3;
}

bool checkVertical(const vector<string>& flag, int n, int m) {
    if (m % 3 != 0) return false;
    int stripeWidth = m / 3;
    set<char> colors;
    for (int i = 0; i < 3; ++i) {
        char c = flag[0][i * stripeWidth];
        colors.insert(c);
        for (int r = 0; r < n; ++r) {
            for (int col = i * stripeWidth; col < (i + 1) * stripeWidth; ++col) {
                if (flag[r][col] != c) return false;
            }
        }
    }
    return colors.size() == 3;
}

