using namespace std;

int main() {
    int n, L;
    cin >> n >> L;
    vector<int> kefa(n), sasha(n);
    for (int i = 0; i < n; i++) cin >> kefa[i];
    for (int i = 0; i < n; i++) cin >> sasha[i];

    // Compute the distances between consecutive barriers for Kefa
    vector<int> kefa_diff(n);
    for (int i = 0; i < n - 1; i++) {
        kefa_diff[i] = kefa[i + 1] - kefa[i];
    }
    kefa_diff[n - 1] = L - kefa[n - 1] + kefa[0];

    // Compute the distances between consecutive barriers for Sasha
    vector<int> sasha_diff(n);
    for (int i = 0; i < n - 1; i++) {
        sasha_diff[i] = sasha[i + 1] - sasha[i];
    }
    sasha_diff[n - 1] = L - sasha[n - 1] + sasha[0];

    // Check if sasha_diff is a rotation of kefa_diff
    // We do this by concatenating sasha_diff with itself and searching for kefa_diff as a subarray
    bool found = false;
    for (int start = 0; start < n; start++) {
        bool match = true;
        for (int i = 0; i < n; i++) {
            if (kefa_diff[i] != sasha_diff[(start + i) % n]) {
                match = false;
                break;
            }
        }
        if (match) {
            found = true;
            break;
        }
    }

    cout << (found ? "YES" : "NO") << "\n";
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

bool is_palindrome(const string& s) {
    int n = s.size();
    for (int i = 0; i < n / 2; i++) {
        if (s[i] != s[n - 1 - i]) return false;
    }
    return true;
}

int main() {
    string s;
    cin >> s;
    int n = (int)s.size();

    if (!is_palindrome(s)) {
        cout << n << "\n";
        return 0;
    }

    // If all characters are the same, all substrings are palindromes
    bool all_same = true;
    for (int i = 1; i < n; i++) {
        if (s[i] != s[0]) {
            all_same = false;
            break;
        }
    }
    if (all_same) {
        cout << 0 << "\n";
        return 0;
    }

    // Since s is palindrome but not all characters are same,
    // the longest non-palindromic substring is n-1
    cout << n - 1 << "\n";
    return 0;
}

