    cin.tie(nullptr);

    int n; 
    cin >> n;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    vector<int> dist(n, n+1);

    // Forward pass
    int last_zero = -n - 1;
    for (int i = 0; i < n; i++) {
        if (a[i] == 0) last_zero = i;
        dist[i] = i - last_zero;
    }

    // Backward pass
    last_zero = 2*n;
    for (int i = n - 1; i >= 0; i--) {
        if (a[i] == 0) last_zero = i;
        dist[i] = min(dist[i], last_zero - i);
    }

    for (int i = 0; i < n; i++) {
        cout << dist[i] << " ";
    }
    cout << "\n";

    return 0;
}

#include <iostream>
#include <algorithm>

using namespace std;

int main() {
    long long d, k, a, b, t;
    cin >> d >> k >> a >> b >> t;

    // If driving the whole distance without repair is cheaper than walking
    if (a * k + t >= b * k) {
        // It's better to walk all the way
        cout << d * b << "\n";
        return 0;
    }

    long long full_segments = d / k;
    long long remainder = d % k;

    // Time if we drive full_segments times with repair (except last if no remainder)
    long long time = 0;

    if (full_segments > 0) {
        // For all but last segment, we pay driving + repair
        time += (full_segments - 1) * (a * k + t);
        // For last full segment, no repair after it if no remainder
        time += a * k;
    }

    // For remainder, choose min between driving or walking
    time += min(remainder * a, remainder * b);

    // Also consider the case when no full segments, just drive or walk remainder
    if (full_segments == 0) {
        time = min(d * a, d * b);
    }

    cout << time << "\n";

    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int main() {
    long long n, k;
    cin >> n >> k;

    // Minimum sum of strictly increasing sequence of length k is k*(k+1)/2
    long long min_sum = k * (k + 1) / 2;
    if (n < min_sum) {
        cout << -1 << "\n";
        return 0;
    }

    // We want to maximize gcd = g
    // So n = g * m, where m >= k*(k+1)/2
    // Find max g dividing n such that m = n/g >= min_sum

    long long g = 1;
    // To find max g, we can iterate over divisors of n up to sqrt(n)
    // But n can be up to 1e10, so sqrt(n) ~ 1e5, which is feasible.

    long long limit = 1e5;
    if (n < limit * limit) limit = (long long)(sqrt(n)) + 1;

    for (long long i = 1; i <= limit; i++) {
        if (n % i == 0) {
            long long d1 = i;
            long long d2 = n / i;

            // Check d1
            if (n / d1 >= min_sum && d1 > g) g = d1;
            // Check d2
            if (n / d2 >= min_sum && d2 > g) g = d2;
        }
    }

    long long m = n / g;

    // Construct sequence: a_i = g * i for i=1..k
    // sum = g * k*(k+1)/2 <= n, and since m >= min_sum, this is valid
    for (long long i = 1; i <= k; i++) {
        cout << g * i;
        if (i != k) cout << " ";
    }
    cout << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; long long x;
    cin >> n >> x;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    // dp0: max subarray sum ending at i without any multiplication
    // dp1: max subarray sum ending at i with multiplication ongoing
    // dp2: max subarray sum ending at i after multiplication ended
    vector<long long> dp0(n+1, 0), dp1(n+1, LLONG_MIN), dp2(n+1, LLONG_MIN);

    long long ans = 0;
    for (int i = 1; i <= n; i++) {
        long long val = a[i-1];
        dp0[i] = max(dp0[i-1] + val, 0LL);
        dp1[i] = max({dp0[i-1] + val * x, dp1[i-1] + val * x, 0LL});
        dp2[i] = max(dp1[i-1] + val, dp2[i-1] + val);
        ans = max({ans, dp0[i], dp1[i], dp2[i]});
    }

    cout << ans << "\n";
    return 0;
}

