#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdint>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    uint64_t n;
    cin >> n;

    vector<uint64_t> results;

    // We try all possible odd numbers of teams x (1 <= x <= 2*10^9 approx)
    // Because after the knockout stages, the remaining teams are odd.
    // For each odd x, total games = (initial knockout games) + round robin games
    // initial knockout games = total initial teams - x
    // total initial teams = x * 2^k for some k >= 0
    // total games = (x * 2^k - x) + x*(x-1)/2 = x*(2^k -1) + x*(x-1)/2 = n
    //
    // So for fixed x:
    // x*(2^k -1) = n - x*(x-1)/2
    // 2^k -1 = (n - x*(x-1)/2)/x
    // 2^k = ((n - x*(x-1)/2)/x) + 1
    //
    // The right side must be a positive integer power of two.
    //
    // We iterate over odd x such that x*(x-1)/2 <= n (otherwise RHS negative)
    // and check if RHS+1 is power of two.

    // To avoid overflow, we use 128-bit integer for intermediate calculations if available.
    // Since n can be up to 10^18, x up to ~2*10^9 is safe for 64-bit multiplication.

    // Upper bound for x:
    // x*(x-1)/2 <= n
    // x^2 <= 2n + x
    // x ~ sqrt(2n)
    // For n=1e18, sqrt(2e18) ~ 1.4e9, so we can iterate up to 2e9 safely.

    // We'll iterate over odd x from 1 to max_x
    uint64_t max_x = 2'000'000'000ULL;
    if (n < 1) {
        cout << -1 << "\n";
        return 0;
    }

    for (uint64_t x = 1; x <= max_x; x += 2) {
        // Compute x*(x-1)/2
        // Check if x*(x-1)/2 > n to break early
        __uint128_t val = (__uint128_t)x * (x - 1) / 2;
        if (val > n) break;

        __uint128_t rhs_num = (__uint128_t)n - val;
        if (rhs_num % x != 0) continue;

        __uint128_t rhs = rhs_num / x + 1; // rhs = 2^k

        // Check if rhs is power of two
        if ((rhs & (rhs - 1)) == 0) {
            // Calculate initial teams = x * 2^k = x * (rhs)
            // Check if initial teams fits in 64-bit
            __uint128_t initial_teams = (__uint128_t)x * rhs;
            if (initial_teams <= UINT64_MAX) {
                results.push_back((uint64_t)initial_teams);
            }
        }
    }

    if (results.empty()) {
        cout << -1 << "\n";
    } else {
        sort(results.begin(), results.end());
        results.erase(unique(results.begin(), results.end()), results.end());
        for (auto &r : results) {
            cout << r << "\n";
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n; cin >> n;
    string s; cin >> s;
    vector<int> b(n);
    for (int i = 0; i < n; i++) cin >> b[i];

    // We want to form an antipalindromic permutation t of s.
    // Conditions:
    // - n is even
    // - For each i, t[i] != t[n - i - 1]
    // - t is a permutation of s
    // Maximize sum of b[i] where s[i] == t[i]

    // Approach:
    // Pair indices (i, n-1-i).
    // For each pair, we must assign two different letters from s.
    // We want to maximize sum of b[i] where s[i] == t[i].
    // For each pair, we try both assignments:
    //   t[i] = c1, t[j] = c2
    //   or t[i] = c2, t[j] = c1
    // and pick the one with max sum of b[i] where s[i] == t[i].

    // We will:
    // 1) Count frequency of letters in s.
    // 2) For each pair (i, j), try all pairs of distinct letters available.
    // 3) Use backtracking with memoization to assign letters to pairs.

    // But n <= 100, so backtracking over pairs is possible if done carefully.

    // Instead, we can model this as a maximum weighted matching problem:
    // Each pair (i, j) must be assigned two distinct letters from s.
    // The letters are limited by frequency.
    // We want to assign letters to pairs to maximize sum of b[i] where s[i] == t[i].

    // Let's group pairs:
    // There are n/2 pairs: (0,n-1), (1,n-2), ..., (n/2-1, n/2)
    // For each pair, we try all pairs of distinct letters (c1, c2) with freq > 0.
    // For each such pair, compute the gain:
    // gain = (s[i] == c1 ? b[i] : 0) + (s[j] == c2 ? b[j] : 0)
    // or swap c1 and c2:
    // gain2 = (s[i] == c2 ? b[i] : 0) + (s[j] == c1 ? b[j] : 0)
    // take max(gain, gain2)

    // We want to assign letters to pairs so that total gain is maximized and letter counts are respected.

    // This is a weighted matching problem with letter frequency constraints.
    // Since n <= 100, we can do DP over pairs and letter counts.

    // Let's implement DP over pairs:
    // State: dp[p][freq], where p is pair index, freq is frequency vector of letters left.
    // But freq vector is too big (26 letters, each up to n).

    // Alternative approach:
    // Since n <= 100, and letters are lowercase (26),
    // we can try a greedy approach:
    // For each pair, try all pairs of distinct letters with freq > 0,
    // pick the pair with max gain, assign letters, reduce freq, continue.

    // But greedy may fail.

    // Another approach:
    // Since the problem guarantees that s can be rearranged into an antipalindromic string,
    // the frequency of each letter is even or letters can be paired properly.

    // Let's try a heuristic:
    // For each pair (i, j), we try all pairs of distinct letters (c1, c2) with freq > 0,
    // compute max gain for that pair.
    // Then we build a weighted bipartite graph:
    // Left side: pairs (i,j)
    // Right side: pairs of letters (c1,c2)
    // Edges: gain for assigning (c1,c2) to pair (i,j)
    // We want to find maximum matching with maximum sum of gains.

    // But number of letter pairs is up to 26*25=650, pairs up to 50.
    // So bipartite graph with 50 nodes on left, 650 on right.

    // We can solve maximum weighted bipartite matching.

    // After matching, assign letters accordingly.

    // Implement Hungarian algorithm for max weighted bipartite matching.

    int half = n / 2;

    // Count frequency of letters
    vector<int> freq(26, 0);
    for (char c : s) freq[c - 'a']++;

    // Generate all pairs of distinct letters with freq > 0
    vector<pair<int,int>> letterPairs;
    for (int c1 = 0; c1 < 26; c1++) {
        if (freq[c1] == 0) continue;
        for (int c2 = 0; c2 < 26; c2++) {
            if (c1 == c2) continue;
            if (freq[c2] == 0) continue;
            letterPairs.emplace_back(c1, c2);
        }
    }

    // For each pair (i, j), compute gain for each letter pair
    // gain = max of:
    //   b[i] if s[i] == c1 + b[j] if s[j] == c2
    //   b[i] if s[i] == c2 + b[j] if s[j] == c1

    // Build cost matrix for Hungarian:
    // rows = half (pairs)
    // cols = letterPairs.size()

    int m = (int)letterPairs.size();
    vector<vector<int>> cost(half, vector<int>(m, INT_MIN));

    for (int p = 0; p < half; p++) {
        int i = p;
        int j = n - 1 - p;
        for (int lp = 0; lp < m; lp++) {
            int c1 = letterPairs[lp].first;
            int c2 = letterPairs[lp].second;
            int gain1 = 0;
            if (s[i] - 'a' == c1) gain1 += b[i];
            if (s[j] - 'a' == c2) gain1 += b[j];
            int gain2 = 0;
            if (s[i] - 'a' == c2) gain2 += b[i];
            if (s[j] - 'a' == c1) gain2 += b[j];
            cost[p][lp] = max(gain1, gain2);
        }
    }

    // Hungarian algorithm for maximum weight matching
    // Implementation adapted for max weight matching

    // Hungarian algorithm implementation
    // Reference: https://pastebin.com/7Q0Xq6qX (modified for max weight)

    int INF = 1e9;
    vector<int> u(half+1), v(m+1), p(m+1), way(m+1);

    for (int i = 1; i <= half; i++) {
        p[0] = i;
        int j0 = 0;
        vector<int> minv(m+1, INF);
        vector<char> used(m+1, false);
        do {
            used[j0] = true;
            int i0 = p[j0], j1 = 0;
            int delta = INF;
            for (int j = 1; j <= m; j++) {
                if (!used[j]) {
                    int cur = -cost[i0-1][j-1] - u[i0] - v[j];
                    if (cur < minv[j]) {
                        minv[j] = cur;
                        way[j] = j0;
                    }
                    if (minv[j] < delta) {
                        delta = minv[j];
                        j1 = j;
                    }
                }
            }
            for (int j = 0; j <= m; j++) {
                if (used[j]) {
                    u[p[j]] += delta;
                    v[j] -= delta;
                } else {
                    minv[j] -= delta;
                }
            }
            j0 = j1;
        } while (p[j0] != 0);
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0);
    }

    // p[j] = matched row for column j
    // p[0] = 0
    // For j in [1..m], if p[j] != 0, then pair p[j]-1 matched with letterPairs[j-1]

    // Check if matching size == half
    // If not, problem constraints guarantee solution, so it should be.

    // Now assign letters to pairs according to matching
    // We must check freq constraints

    vector<int> freqCopy = freq;
    vector<char> t(n);

    for (int j = 1; j <= m; j++) {
        int i = p[j];
        if (i == 0) continue;
        int pairIdx = i - 1;
        int c1 = letterPairs[j-1].first;
        int c2 = letterPairs[j-1].second;
        int left = pairIdx;
        int right = n - 1 - pairIdx;

        // Decide assignment to maximize gain
        int gain1 = 0;
        if (s[left] - 'a' == c1) gain1 += b[left];
        if (s[right] - 'a' == c2) gain1 += b[right];
        int gain2 = 0;
        if (s[left] - 'a' == c2) gain2 += b[left];
        if (s[right] - 'a' == c1) gain2 += b[right];

        if (gain1 >= gain2) {
            // assign c1 to left, c2 to right
            t[left] = (char)(c1 + 'a');
            t[right] = (char)(c2 + 'a');
            freqCopy[c1]--;
            freqCopy[c2]--;
        } else {
            // assign c2 to left, c1 to right
            t[left] = (char)(c2 + 'a');
            t[right] = (char)(c1 + 'a');
            freqCopy[c2]--;
            freqCopy[c1]--;
        }
    }

    // Compute final beauty
    int ans = 0;
    for (int i = 0; i < n; i++) {
        if (s[i] == t[i]) ans += b[i];
    }

    cout << ans << "\n";

    return 0;
}

