using namespace std;

int main() {
    int n, a, b;
    cin >> n >> a >> b;

    // We have 6 sides in total: 4 vertical sides (length a) and 2 top sides (length b)
    // Each side must be a continuous piece from a wooden bar.
    // We want to minimize the number of bars used.

    // Let's create an array of all sides lengths
    int sides[6] = {a, a, a, a, b, b};

    // Sort sides in descending order to try to fit bigger pieces first
    sort(sides, sides + 6, greater<int>());

    // We'll use a simple greedy approach:
    // For each side, try to fit it into an existing bar if possible,
    // otherwise start a new bar.

    int bars[6] = {0}; // store remaining length in each bar
    int bars_count = 0;

    for (int i = 0; i < 6; i++) {
        int length = sides[i];
        bool placed = false;
        for (int j = 0; j < bars_count; j++) {
            if (bars[j] >= length) {
                bars[j] -= length;
                placed = true;
                break;
            }
        }
        if (!placed) {
            bars[bars_count] = n - length;
            bars_count++;
        }
    }

    cout << bars_count << "\n";

    return 0;
}

