#include <iostream>
#include <string>

using namespace std;

int main() {
    string seat;
    cin >> seat;

    // Parse input: row number and seat letter
    int i = 0;
    while (i < (int)seat.size() && isdigit(seat[i])) i++;
    long long n = stoll(seat.substr(0, i));
    char s = seat[i];

    // Determine which attendant serves row n and the serving order
    // Attendants serve rows in pairs with a pattern of moves:
    // Moves: 2 rows forward, then 1 row forward, then 3 rows forward, then 1 row forward, repeating
    // The first attendant serves rows: 1,2,5,6,9,10,...
    // The second attendant serves rows: 3,4,7,8,11,12,...
    // Pattern repeats every 4 rows:
    // For rows 1-4:
    //   first attendant: 1,2
    //   second attendant: 3,4
    // For rows 5-8:
    //   first attendant: 5,6
    //   second attendant: 7,8
    // and so on.

    // So rows can be grouped in blocks of 4:
    // block = (n-1)/4
    // position in block = (n-1)%4
    // if position in block < 2 => first attendant
    // else second attendant

    long long block = (n - 1) / 4;
    int pos = (n - 1) % 4;

    bool first_attendant = (pos < 2);

    // Calculate total time before serving row n

    // Each block of 4 rows corresponds to a cycle of moves and serving:
    // The time to serve each row is 6 seconds (6 passengers * 1 second each)
    // The moves between pairs are:
    // After serving rows 1 and 3, move 1 row forward (1 second)
    // After serving rows 2 and 4, move 3 rows forward (3 seconds)
    // Then after serving rows 5 and 7, move 1 row forward (1 second)
    // After serving rows 6 and 8, move 3 rows forward (3 seconds)
    // and so on.

    // But the problem states the attendants move as follows:
    // Start: first attendant at row 1, second at row 3
    // After both finish, move one row forward (1 second)
    // Then first attendant serves row 2, second serves row 4
    // After both finish, move three rows forward (3 seconds)
    // Then first attendant serves row 5, second serves row 7
    // After both finish, move one row forward (1 second)
    // Then first attendant serves row 6, second serves row 8
    // After both finish, move three rows forward (3 seconds)
    // and so on.

    // So the pattern of moves between pairs is: 1,3,1,3,1,3,...
    // Each pair of rows served takes 6 seconds per row * 2 rows = 12 seconds
    // Then move time (1 or 3 seconds) before next pair

    // Let's define the sequence of pairs:
    // pair 0: rows 1 and 3
    // pair 1: rows 2 and 4
    // pair 2: rows 5 and 7
    // pair 3: rows 6 and 8
    // pair 4: rows 9 and 11
    // pair 5: rows 10 and 12
    // and so on.

    // The pairs alternate between moving 1 second and 3 seconds after serving.

    // Let's find which pair the row n belongs to.

    // For first attendant rows: 1,2,5,6,9,10,...
    // For second attendant rows: 3,4,7,8,11,12,...

    // Let's map row n to pair index:
    // For first attendant rows:
    // rows: 1,2,5,6,9,10,...
    // pair indices: 0,1,2,3,4,5,...
    // For second attendant rows:
    // rows: 3,4,7,8,11,12,...
    // pair indices: 0,1,2,3,4,5,...

    // So pair index = ( (n-1) / 2 )

    long long pair_index = (n - 1) / 2;

    // Total time before serving pair_index pairs:
    // Each pair serving time: 12 seconds (6 + 6)
    // Moves after pairs alternate: after even pairs move 1 second, after odd pairs move 3 seconds
    // But the last pair served before n is pair_index - 1, so sum moves for pairs before pair_index

    // Sum serving time for all previous pairs:
    long long total_time = pair_index * 12;

    // Sum move times after previous pairs:
    // Moves after pairs 0,2,4,... are 1 second
    // Moves after pairs 1,3,5,... are 3 seconds
    // Number of moves = pair_index (except no move after last pair)
    // So sum moves for i=0 to pair_index-1:
    // if i even -> 1 second
    // if i odd -> 3 seconds

    long long moves_time = 0;
    for (long long i = 0; i < pair_index; i++) {
        moves_time += (i % 2 == 0) ? 1 : 3;
    }

    total_time += moves_time;

    // Now add the time within the row to serve seat s

    // Serving order per row:
    // First right side seats: f, e, d (window to aisle)
    // Then left side seats: a, b, c (window to aisle)
    // Each passenger takes 1 second

    // Map seat to position in serving order (1-based):
    // f -> 1
    // e -> 2
    // d -> 3
    // a -> 4
    // b -> 5
    // c -> 6

    int seat_pos;
    switch (s) {
        case 'f': seat_pos = 1; break;
        case 'e': seat_pos = 2; break;
        case 'd': seat_pos = 3; break;
        case 'a': seat_pos = 4; break;
        case 'b': seat_pos = 5; break;
        case 'c': seat_pos = 6; break;
        default: seat_pos = 0; // should not happen
    }

    // Add seat_pos seconds to total_time
    total_time += seat_pos;

    cout << total_time << "\n";

    return 0;
}

