    // For each position i, compare X[i]* (bx^(n-1-i)) and Y[i]* (by^(m-1-i))
    // But direct power comparison is complicated.
    // Instead, compare digit by digit from most significant to least significant:
    // At first differing digit, compare their values after converting to decimal.

    // To avoid overflow, we compare digit by digit:
    // For each position i:
    //   If X[i] == Y[i] and bx == by, continue
    //   Else, compare X[i]* (bx^(n-1-i)) and Y[i]* (by^(m-1-i))
    // But powers can be huge, so we do a direct comparison by simulating.

    // Since n == m, we can compare digit by digit:
    // For each i:
    //   If X[i] == Y[i], continue
    //   Else if X[i] > Y[i], output '>' and return
    //   Else output '<' and return

    // But digits are in different bases, so digits are not directly comparable.
    // For example, digit 2 in base 3 is not equal to digit 2 in base 5.

    // So we need to compare the values of the numbers.

    // Since n and m <= 10, and bases <= 40, the maximum value fits in 64-bit integer.

    unsigned long long valX = 0, valY = 0;
    for (int i = 0; i < n; i++) {
        valX = valX * bx + X[i];
    }
    for (int i = 0; i < m; i++) {
        valY = valY * by + Y[i];
    }

    if (valX < valY) cout << "<" << endl;
    else if (valX > valY) cout << ">" << endl;
    else cout << "=" << endl;

    return 0;
}

