int main() {
    int x, y, z;
    cin >> x >> y >> z;

    int min_up = x;
    int max_up = x + z;
    int min_down = y;
    int max_down = y + z;

    // Check all possible results
    bool can_plus = false, can_minus = false, can_zero = false;

    // The difference between upvotes and downvotes can range from (x - (y+z)) to ((x+z) - y)
    // We check if there exists a scenario for each result.

    // Check if "+" is possible
    // "+" means upvotes > downvotes
    // So, check if max_up > min_down
    if (max_up > min_down) can_plus = true;

    // Check if "-" is possible
    // "-" means downvotes > upvotes
    // So, check if max_down > min_up
    if (max_down > min_up) can_minus = true;

    // Check if "0" is possible
    // "0" means upvotes == downvotes
    // So, check if there exists k in [0,z] such that x + k == y + (z - k)
    // => x + k = y + z - k
    // => 2k = y + z - x
    // => k = (y + z - x)/2
    int diff = y + z - x;
    if (diff >= 0 && diff <= 2*z && diff % 2 == 0) {
        int k = diff / 2;
        if (k >= 0 && k <= z) can_zero = true;
    }

    int count = can_plus + can_minus + can_zero;

    if (count > 1) cout << "?" << endl;
    else if (can_plus) cout << "+" << endl;
    else if (can_minus) cout << "-" << endl;
    else cout << "0" << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; cin >> n;
    string s; cin >> s;
    int x, y; cin >> x >> y;

    // Prefix sums for x and y coordinates after each operation
    vector<int> px(n + 1, 0), py(n + 1, 0);
    for (int i = 0; i < n; i++) {
        px[i + 1] = px[i];
        py[i + 1] = py[i];
        if (s[i] == 'U') py[i + 1]++;
        else if (s[i] == 'D') py[i + 1]--;
        else if (s[i] == 'L') px[i + 1]--;
        else if (s[i] == 'R') px[i + 1]++;
    }

    // If no changes needed
    if (px[n] == x && py[n] == y) {
        cout << 0 << "\n";
        return 0;
    }

    // If impossible: length of changed subsegment must be even or odd?
    // Actually, if |x - px[n]| + |y - py[n]| > n or parity mismatch, no solution
    int dist = abs(x - px[n]) + abs(y - py[n]);
    if (dist > n || (dist % 2 != n % 2)) {
        cout << -1 << "\n";
        return 0;
    }

    int ans = n + 1;
    int j = 0;

    // Sliding window approach:
    // We try to find minimal length subsegment [i, j) to change so that after changing it,
    // the robot ends at (x, y).
    // The idea: 
    // final position = prefix before i + changed segment + suffix after j
    // changed segment can be anything, so we want to check if we can fix the difference by changing [i, j)
    // The difference after removing [i, j) is:
    // dx = px[n] - (px[j] - px[i])
    // dy = py[n] - (py[j] - py[i])
    // We want to change the subsegment to fix the difference to (x, y):
    // So the difference we need to fix is (x - dx, y - dy)
    // The length of subsegment is (j - i)
    // We can fix the difference if the Manhattan distance <= length and parity matches

    for (int i = 0; i <= n; i++) {
        while (j <= n) {
            int dx = px[n] - (px[j] - px[i]);
            int dy = py[n] - (py[j] - py[i]);
            int len = j - i;
            int need = abs(x - dx) + abs(y - dy);
            if (need <= len && (need % 2) == (len % 2)) {
                ans = min(ans, len);
                break;
            }
            j++;
        }
        if (j == n + 1) break;
    }

    if (ans == n + 1) cout << -1 << "\n";
    else cout << ans << "\n";

    return 0;
}

