    int T; cin >> T;
    while (T--) {
        int n; long long x;
        cin >> n >> x;
        string s; cin >> s;

        vector<long long> prefix_balance(n + 1, 0);
        for (int i = 0; i < n; i++) {
            prefix_balance[i + 1] = prefix_balance[i] + (s[i] == '0' ? 1 : -1);
        }

        long long total_balance = prefix_balance[n];

        // If total_balance == 0, then the balance repeats every n characters
        if (total_balance == 0) {
            // Check if any prefix_balance[i] == x
            bool found = false;
            for (int i = 0; i <= n; i++) {
                if (prefix_balance[i] == x) {
                    found = true;
                    break;
                }
            }
            cout << (found ? -1 : 0) << "\n";
        } else {
            // total_balance != 0
            // We want to count number of prefixes p = k*n + i (0 <= i <= n)
            // such that prefix_balance[i] + k*total_balance == x and k >= 0
            long long ans = 0;
            for (int i = 0; i <= n; i++) {
                long long diff = x - prefix_balance[i];
                if (diff % total_balance == 0) {
                    long long k = diff / total_balance;
                    if (k >= 0) ans++;
                }
            }
            cout << ans << "\n";
        }
    }

    return 0;
}

