#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m, k, x, y;
    cin >> n >> m >> k >> x >> y;

    if (n == 1) {
        // Only one row, teacher always asks this row
        long long full = k / m;
        long long rem = k % m;
        long long maxq = full + (rem > 0 ? 1 : 0);
        long long minq = full;
        long long sergei = full + (y <= rem ? 1 : 0);
        cout << maxq << " " << minq << " " << sergei << "\n";
        return 0;
    }

    // For n > 1
    // The pattern of rows asked is:
    // 1,2,...,n-1,n,n-1,...,2,1,2,...
    // The length of one full cycle in rows is 2*(n-1)
    long long cycle_len = 2 * (n - 1);
    long long cycle_questions = cycle_len * m;

    long long full_cycles = k / cycle_questions;
    long long rem = k % cycle_questions;

    // Count how many times each row is asked in one full cycle
    // rows 1 and n are asked once per cycle
    // rows 2..n-1 are asked twice per cycle
    // So total questions per row per cycle:
    // row 1: m times
    // row n: m times
    // rows 2..n-1: 2*m times

    // Calculate base questions per row after full cycles
    // For each row:
    // if row == 1 or row == n: base = full_cycles * m
    // else base = full_cycles * 2 * m

    // Now distribute the remainder rem over the rows in order:
    // rows 1..n, then n-1..2

    // We'll simulate the remainder distribution over rows in order

    // Create an array to store questions per row from remainder
    long long rem_questions_per_row[101] = {0};

    // The order of rows in one cycle:
    // rows 1..n
    // rows n-1..2
    // total cycle_len rows

    // We'll iterate over rows in order until rem is 0

    // First half: rows 1..n
    for (long long row = 1; row <= n && rem > 0; ++row) {
        long long ask = min(rem, m);
        rem_questions_per_row[row] += ask;
        rem -= ask;
    }
    // Second half: rows n-1..2
    for (long long row = n - 1; row >= 2 && rem > 0; --row) {
        long long ask = min(rem, m);
        rem_questions_per_row[row] += ask;
        rem -= ask;
    }

    // Now calculate total questions per row
    long long questions_per_row[101];
    for (long long row = 1; row <= n; ++row) {
        if (row == 1 || row == n) {
            questions_per_row[row] = full_cycles * m + rem_questions_per_row[row];
        } else {
            questions_per_row[row] = full_cycles * 2 * m + rem_questions_per_row[row];
        }
    }

    // Now find max and min questions per pupil
    // Each pupil in a row is asked floor(questions_per_row[row]/m) times
    // plus one if their seat number <= questions_per_row[row] % m

    long long maxq = 0, minq = 1e18;

    for (long long row = 1; row <= n; ++row) {
        long long full = questions_per_row[row] / m;
        long long rem_p = questions_per_row[row] % m;
        for (long long seat = 1; seat <= m; ++seat) {
            long long q = full + (seat <= rem_p ? 1 : 0);
            if (q > maxq) maxq = q;
            if (q < minq) minq = q;
        }
    }

    // Calculate Sergei's questions
    long long sergei_full = questions_per_row[x] / m;
    long long sergei_rem = questions_per_row[x] % m;
    long long sergei = sergei_full + (y <= sergei_rem ? 1 : 0);

    cout << maxq << " " << minq << " " << sergei << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int max_beauty(const string &s, long long n) {
    int len = (int)s.size();
    // Count frequency of each character
    vector<int> freq(256, 0);
    for (char c : s) freq[(unsigned char)c]++;
    int max_freq = *max_element(freq.begin(), freq.end());

    // If n < len, max beauty is min(len, max_freq + n)
    // If n >= len, max beauty is len (can change all chars to same)
    if (n < len) {
        // Special case: if max_freq == len and n == 1 and all chars same,
        // changing one char to different reduces max freq by 1
        // But since we want max beauty, we consider max_freq + n capped by len
        // However, if max_freq == len and n == 1 and len == 1, max_freq + n = 2 > len
        // So cap by len anyway
        return min(len, max_freq + (int)n);
    } else {
        // n >= len, can make all chars same
        // But if len == 1 and n >= 1, max beauty is 1 anyway
        return len;
    }
}

