    long long dp_even = 0;
    long long dp_odd = LLONG_MIN;

    for(int i = 0; i < n; i++) {
        long long x = a[i];
        long long new_even = dp_even, new_odd = dp_odd;

        // Add current element to even sum subsequence
        if (dp_even != LLONG_MIN) {
            long long val = dp_even + x;
            if (val % 2 == 0) new_even = max(new_even, val);
            else new_odd = max(new_odd, val);
        }

        // Add current element to odd sum subsequence
        if (dp_odd != LLONG_MIN) {
            long long val = dp_odd + x;
            if (val % 2 == 0) new_even = max(new_even, val);
            else new_odd = max(new_odd, val);
        }

        // Start new subsequence with current element alone
        if (x % 2 == 0) new_even = max(new_even, x);
        else new_odd = max(new_odd, x);

        dp_even = new_even;
        dp_odd = new_odd;
    }

    cout << dp_odd << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll gcd_ll(ll a, ll b) {
    while (b) {
        ll t = b;
        b = a % b;
        a = t;
    }
    return a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a, b;
    cin >> a >> b;
    if (a == b) {
        cout << 0 << "\n";
        return 0;
    }

    if (a > b) swap(a, b);
    ll diff = b - a;

    // We want to find k >= 0 minimizing lcm(a+k, b+k)
    // lcm(a+k, b+k) = ((a+k)*(b+k)) / gcd(a+k, b+k)
    // Since gcd(a+k, b+k) divides their difference, gcd(a+k, b+k) divides diff.
    // So gcd(a+k, b+k) is a divisor of diff.
    // For each divisor d of diff, we can try k = (d - a % d) % d
    // and compute lcm, pick minimal lcm and minimal k.

    ll res_k = 0;
    __int128 res_lcm = (__int128)(a) * b / gcd_ll(a, b); // initial lcm at k=0

    // Find divisors of diff
    vector<ll> divisors;
    for (ll i = 1; i * i <= diff; i++) {
        if (diff % i == 0) {
            divisors.push_back(i);
            if (i * i != diff) divisors.push_back(diff / i);
        }
    }

    for (ll d : divisors) {
        ll k = (d - (a % d)) % d;
        ll A = a + k;
        ll B = b + k;
        ll g = gcd_ll(A, B);
        // To avoid overflow, use __int128
        __int128 l = (__int128)A / g * B;
        if (l < res_lcm || (l == res_lcm && k < res_k)) {
            res_lcm = l;
            res_k = k;
        }
    }

    cout << res_k << "\n";

    return 0;
}

