#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct State {
    ll a, b;
    int steps;
    State(ll a, ll b, int steps) : a(a), b(b), steps(steps) {}
};

bool canHalf(ll x) {
    return x % 2 == 0;
}

bool canThird(ll x) {
    return x % 3 == 0;
}

vector<State> nextStates(State s) {
    vector<State> res;
    ll a = s.a, b = s.b, steps = s.steps;

    // Try half on a
    if (canHalf(a)) {
        res.emplace_back(a / 2, b, steps + 1);
    }
    // Try half on b
    if (canHalf(b)) {
        res.emplace_back(a, b / 2, steps + 1);
    }
    // Try third on a
    if (canThird(a)) {
        // eat one third -> left 2/3
        res.emplace_back(a * 2 / 3, b, steps + 1);
    }
    // Try third on b
    if (canThird(b)) {
        res.emplace_back(a, b * 2 / 3, steps + 1);
    }
    return res;
}

// Normalize pair so that a <= b (to avoid duplicates with swapped dimensions)
pair<ll,ll> norm(ll a, ll b) {
    if (a > b) swap(a, b);
    return {a, b};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a1, b1, a2, b2;
    cin >> a1 >> b1 >> a2 >> b2;

    // We want to find minimal steps to make a1*b1 == a2*b2 after some operations
    // Each operation reduces one bar by half or by one third (in one dimension)
    // We can do BFS from both bars independently to find all reachable states with steps

    // BFS from first bar
    map<pair<ll,ll>, int> dist1;
    queue<State> q1;
    auto start1 = norm(a1,b1);
    dist1[start1] = 0;
    q1.emplace(start1.first, start1.second, 0);

    while (!q1.empty()) {
        State cur = q1.front(); q1.pop();
        if (cur.steps >= 40) continue; // limit steps to avoid TLE (heuristic)
        for (auto &nxt : nextStates(cur)) {
            auto p = norm(nxt.a, nxt.b);
            if (!dist1.count(p)) {
                dist1[p] = nxt.steps;
                q1.emplace(nxt.a, nxt.b, nxt.steps);
            }
        }
    }

    // BFS from second bar
    map<pair<ll,ll>, int> dist2;
    queue<State> q2;
    auto start2 = norm(a2,b2);
    dist2[start2] = 0;
    q2.emplace(start2.first, start2.second, 0);

    while (!q2.empty()) {
        State cur = q2.front(); q2.pop();
        if (cur.steps >= 40) continue; // limit steps to avoid TLE (heuristic)
        for (auto &nxt : nextStates(cur)) {
            auto p = norm(nxt.a, nxt.b);
            if (!dist2.count(p)) {
                dist2[p] = nxt.steps;
                q2.emplace(nxt.a, nxt.b, nxt.steps);
            }
        }
    }

    // Find common states with same area and minimal sum of steps
    int ans = INT_MAX;
    pair<ll,ll> res1 = {-1,-1}, res2 = {-1,-1};

    for (auto &it1 : dist1) {
        auto p1 = it1.first;
        int d1 = it1.second;
        ll area1 = p1.first * p1.second;
        // For this area, check if dist2 has any state with same area
        // We can iterate dist2 and check area equality, but that is O(n^2)
        // Instead, we can group dist2 states by area for faster lookup

        // To optimize, we can build a map from area to vector of states for dist2
        // But since constraints are large, we do a direct check here with pruning

        // We'll do a map from area to vector for dist2 once
        // Let's build it once outside the loop

        // So let's do that now:
    }

    // Build area -> vector of (state, dist) for dist2
    unordered_map<ll, vector<pair<pair<ll,ll>, int>>> area_map2;
    for (auto &it2 : dist2) {
        ll area = it2.first.first * it2.first.second;
        area_map2[area].emplace_back(it2.first, it2.second);
    }

    for (auto &it1 : dist1) {
        auto p1 = it1.first;
        int d1 = it1.second;
        ll area1 = p1.first * p1.second;
        if (area_map2.count(area1)) {
            for (auto &st2 : area_map2[area1]) {
                int d2 = st2.second;
                int total = d1 + d2;
                if (total < ans) {
                    ans = total;
                    res1 = p1;
                    res2 = st2.first;
                }
            }
        }
    }

    if (ans == INT_MAX) {
        cout << -1 << "\n";
        return 0;
    }

    cout << ans << "\n";
    cout << res1.first << " " << res1.second << "\n";
    cout << res2.first << " " << res2.second << "\n";

    return 0;
}

