#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

typedef unsigned long long ull;

vector<ull> numbers;

void generate() {
    // Numbers with exactly one zero in binary representation
    // For length l (bits), place zero at position p (0-based from right)
    // The number is all ones except one zero at position p
    // For example, for l=11, p=5: number = (1<<11)-1 - (1<<5)
    for (int length = 2; length <= 60; ++length) {
        ull full = (1ULL << length) - 1;
        for (int zero_pos = 0; zero_pos < length; ++zero_pos) {
            ull num = full - (1ULL << zero_pos);
            numbers.push_back(num);
        }
    }
    sort(numbers.begin(), numbers.end());
}

