    cin >> a >> b;

    generate();

    // Count how many numbers in [a,b]
    auto left = lower_bound(numbers.begin(), numbers.end(), a);
    auto right = upper_bound(numbers.begin(), numbers.end(), b);

    cout << right - left << "\n";

    return 0;
}

