int main() {
    int N;
    cin >> N;
    // The minimal number of layers equals the maximum number of segments overlapping at any point.
    // For segments [i,j] with 0 <= i < j <= N, the maximum overlap occurs at the midpoint between integers.
    // The maximum overlap is the maximum number of segments covering a point between two consecutive integers.
    // It can be shown that the maximum overlap is (N+1)*N/2 - sum of layers below.
    // But from the examples and problem, the minimal number of layers equals the maximum number of segments covering any point.
    // The maximum overlap is the maximum number of segments covering a point between two integers k and k+1.
    // Number of segments covering point between k and k+1 is (k+1)*(N - k).
    // We find max over k=0..N-1 of (k+1)*(N-k).
    int max_layers = 0;
    for (int k = 0; k < N; ++k) {
        int overlap = (k + 1) * (N - k);
        if (overlap > max_layers) max_layers = overlap;
    }
    cout << max_layers << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

string serialize(const vector<string>& grid) {
    return grid[0] + grid[1];
}

vector<string> deserialize(const string& s) {
    return {s.substr(0,2), s.substr(2,2)};
}

vector<string> get_neighbors(const vector<string>& grid) {
    vector<string> res;
    int r, c;
    // find empty cell 'X'
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 2; j++)
            if (grid[i][j] == 'X') {
                r = i; c = j;
            }
    // directions: up, down, left, right
    int dr[] = {-1,1,0,0};
    int dc[] = {0,0,-1,1};
    for (int d = 0; d < 4; d++) {
        int nr = r + dr[d], nc = c + dc[d];
        if (nr >= 0 && nr < 2 && nc >= 0 && nc < 2) {
            vector<string> new_grid = grid;
            swap(new_grid[r][c], new_grid[nr][nc]);
            res.push_back(serialize(new_grid));
        }
    }
    return res;
}

set<string> bfs(const vector<string>& start) {
    set<string> visited;
    queue<string> q;
    string s = serialize(start);
    visited.insert(s);
    q.push(s);
    while (!q.empty()) {
        string cur = q.front(); q.pop();
        vector<string> grid = deserialize(cur);
        for (auto& nxt : get_neighbors(grid)) {
            if (!visited.count(nxt)) {
                visited.insert(nxt);
                q.push(nxt);
            }
        }
    }
    return visited;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<string> bessie(2), elsie(2);
    cin >> bessie[0] >> bessie[1];
    cin >> elsie[0] >> elsie[1];

    set<string> bessie_states = bfs(bessie);
    set<string> elsie_states = bfs(elsie);

    for (const string& state : bessie_states) {
        if (elsie_states.count(state)) {
            cout << "YES\n";
            return 0;
        }
    }
    cout << "NO\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    unsigned long long n;
    string k;
    cin >> n >> k;

    // k is the representation of the number in base n, but digits can be > 9 (e.g. 11, 13)
    // So we need to parse k as a sequence of decimal digits, but each digit can be multiple decimal digits.
    // However, problem states: "All digits in the second line are strictly less than n."
    // But digits are decimal numbers concatenated, e.g. "11311" means digits: 1, 13, 11
    // So we need to split k into digits, each digit < n, but digits can be multiple decimal digits.
    // The problem is to find the minimal decimal number x such that when converted to base n, the digits concatenated as decimal numbers form k.

    // The problem is to split k into digits d_0, d_1, ..., d_m-1, each digit < n,
    // and then compute x = sum d_i * n^(m-1 - i).
    // Among all possible splits, find minimal x.

    // Since n can be up to 10^9, digits can be up to 9 or 10 digits long.
    // k length <= 60, so we can do DP to split k into digits.

    int len = (int)k.size();
    vector<unsigned long long> pow_n(len+1, 1);
    for (int i = 1; i <= len; i++) {
        if (pow_n[i-1] > 1e18 / n) pow_n[i] = 1e19; // overflow protection
        else pow_n[i] = pow_n[i-1] * n;
    }

    // dp[i] = minimal decimal number for suffix k[i..end)
    // We'll do from right to left
    // To avoid overflow, store dp[i] as unsigned long long, or 1e19 as INF
    // Also store if dp[i] is valid

    vector<unsigned long long> dp(len+1, ULLONG_MAX);
    dp[len] = 0;

    // We'll try all splits from i to j (j > i), parse k[i..j-1] as digit d
    // if d < n, dp[i] = min(dp[i], d * n^(len - j) + dp[j])

    for (int i = len - 1; i >= 0; i--) {
        unsigned long long val = 0;
        for (int j = i; j < len; j++) {
            // parse k[i..j]
            val = val * 10 + (k[j] - '0');
            if (val >= n) break;
            int power = len - (j + 1);
            if (dp[j+1] == ULLONG_MAX) continue;
            if (pow_n[power] > 1e18 / val) continue; // overflow check for val * pow_n[power]
            unsigned long long cur = val * pow_n[power];
            if (cur > 1e18) continue;
            if (dp[j+1] > 1e18 - cur) continue;
            unsigned long long candidate = cur + dp[j+1];
            if (candidate <= 1e18 && candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }

    cout << dp[0] << "\n";

    return 0;
}

