using namespace std;
using ll = long long;

ll n, k;

// Function to count how many x in [1..n] have y in path(x)
ll count_y(ll y) {
    if (y == 0) return 0;
    if (y == 1) return n;

    if (y % 2 == 0) {
        // y even: count_y(y) = count_y(y/2) + number of x in [1..n] with x=y
        // Actually, count_y(y) = count_y(y/2) + (1 if y <= n else 0)
        // But from problem definition, path(y) always contains y, so count_y(y) >= 1 if y <= n
        // But we must count all x with y in path(x)
        // The formula is count_y(y) = count_y(y/2) + count of x with x=y (which is 1 if y<=n else 0)
        // But the problem examples show that count_y(y) = count_y(y/2) + count of x with x=y
        // Actually, from the problem, count_y(y) = count_y(y/2) + count of x with x=y
        // But x=y is only one number, so +1 if y<=n else 0
        // But the problem examples show that count_y(y) = count_y(y/2) + count of x with x=y
        // Actually, the problem states count_y(y) = count_y(y/2) + count of x with x=y
        // But the problem examples show that count_y(y) = count_y(y/2) + count of x with x=y
        // So we can write count_y(y) = count_y(y/2) + (y <= n ? 1 : 0)
        // But this is not enough, because for odd y, count_y(y) = count_y(y+1)
        // So we must be careful.

        // Actually, from the problem and examples:
        // count_y(y) = count_y(y/2) + count of x with x=y
        // But count of x with x=y is 1 if y <= n else 0
        // So count_y(y) = count_y(y/2) + (y <= n ? 1 : 0)
        return count_y(y / 2) + (y <= n ? 1 : 0);
    } else {
        // y odd: count_y(y) = count_y(y+1)
        if (y + 1 > n) return 0;
        return count_y(y + 1);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k;

    // Binary search for maximum y in [1..n] with count_y(y) >= k
    ll left = 1, right = n, ans = 1;
    while (left <= right) {
        ll mid = left + (right - left) / 2;
        ll c = count_y(mid);
        if (c >= k) {
            ans = mid;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    cout << ans << "\n";

    return 0;
}

#include <iostream>
#include <tuple>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, m, x, y, vx, vy;
    cin >> n >> m >> x >> y >> vx >> vy;

    // If vx == 0 and vy == 0 impossible by problem statement
    // The ball moves indefinitely if it never reaches a corner.

    // The ball moves with reflections:
    // The ball's position after t units of time:
    // For x:
    // pos_x(t) = x + vx * t, but reflected between 0 and n
    // Reflection can be modeled by "mirroring" the coordinate on [0, n]:
    // pos_x(t) = f(x + vx * t, n)
    // where f(p, L) = p mod (2L)
    // if f(p, L) > L then pos = 2L - f(p, L) else pos = f(p, L)

    // Similarly for y.

    // The ball falls into a pocket if pos_x(t) in {0, n} and pos_y(t) in {0, m} at some t >= 0 integer.

    // We want to find t >= 0 integer such that:
    // pos_x(t) in {0, n}
    // pos_y(t) in {0, m}

    // Let's define a function to get the "reflected coordinate" at time t:
    // But we want to find t such that pos_x(t) == 0 or n and pos_y(t) == 0 or m.

    // Let's consider the "extended" coordinate:
    // For x:
    // X(t) = x + vx * t
    // The reflected coordinate is:
    // rX(t) = X(t) mod (2n)
    // if rX(t) > n then pos_x(t) = 2n - rX(t)
    // else pos_x(t) = rX(t)

    // pos_x(t) == 0 or n means rX(t) == 0 or n

    // So we want t such that:
    // (x + vx * t) mod (2n) == 0 or n
    // and
    // (y + vy * t) mod (2m) == 0 or m

    // vx and vy are in {-1,0,1}, so we can handle zero velocity separately.

    // If vx == 0:
    // pos_x(t) = x constant
    // For ball to fall into pocket, x must be 0 or n
    // If not, no pocket possible.

    // Similarly for vy == 0.

    // So first check if vx == 0 and x not in {0,n} => no pocket
    // Similarly for vy == 0 and y not in {0,m} => no pocket

    // Then for vx != 0:
    // We want to find t >= 0 integer such that:
    // (x + vx * t) mod (2n) == 0 or n
    // Similarly for y.

    // Let's define a function to find minimal t >= 0 satisfying:
    // (start + dir * t) mod (2L) == target
    // where target in {0, L}

    // We'll try both targets 0 and L for x and y, and find t satisfying both.

    // For each combination of x_target in {0,n} and y_target in {0,m}:
    // Solve:
    // (x + vx * t) mod (2n) == x_target
    // (y + vy * t) mod (2m) == y_target

    // If vx == 0:
    // Check if x == x_target, else no solution for that target.

    // Similarly for vy == 0.

    // For vx != 0:
    // Solve linear congruence:
    // vx * t ≡ (x_target - x) mod 2n

    // Similarly for y.

    // Then find t satisfying both congruences using CRT.

    // If no solution, try next target.

    // If multiple solutions, pick minimal t >= 0.

    // If no solution for any target, print -1.

    // Implement extended Euclidean algorithm for modular inverse and CRT.

    auto ext_gcd = [](ll a, ll b, ll &x, ll &y) -> ll {
        if (b == 0) {
            x = 1; y = 0;
            return a;
        }
        ll x1, y1;
        ll d = ext_gcd(b, a % b, x1, y1);
        x = y1;
        y = x1 - (a / b) * y1;
        return d;
    };

    // Solve a * t ≡ b (mod m)
    // Returns pair<bool, t0> where t0 is minimal non-negative solution modulo m/g
    auto solve_congruence = [&](ll a, ll b, ll m) -> pair<bool, ll> {
        // Solve a t ≡ b mod m
        // gcd(a,m) = g
        // solution exists if g divides b
        ll x, y;
        ll g = ext_gcd(a, m, x, y);
        if (b % g != 0) return {false, 0};
        a /= g; b /= g; m /= g;
        x = (x % m + m) % m;
        ll t0 = (x * b) % m;
        return {true, t0};
    };

    // CRT for two congruences:
    // t ≡ r1 mod m1
    // t ≡ r2 mod m2
    // Returns pair<bool, (t, lcm)> or {false,0} if no solution
    auto crt = [&](ll r1, ll m1, ll r2, ll m2) -> pair<bool, pair<ll,ll>> {
        // Solve t ≡ r1 mod m1
        //       t ≡ r2 mod m2
        // Using extended Euclid on m1 and m2
        ll x, y;
        ll g = ext_gcd(m1, m2, x, y);
        if ((r2 - r1) % g != 0) return {false, {0,0}};
        ll lcm = m1 / g * m2;
        ll diff = (r2 - r1) / g;
        x = (x % (m2/g) + (m2/g)) % (m2/g);
        ll t = (r1 + m1 * ((diff * x) % (m2/g))) % lcm;
        if (t < 0) t += lcm;
        return {true, {t, lcm}};
    };

    // Check zero velocity cases:
    if (vx == 0) {
        if (x != 0 && x != n) {
            cout << -1 << "\n";
            return 0;
        }
    }
    if (vy == 0) {
        if (y != 0 && y != m) {
            cout << -1 << "\n";
            return 0;
        }
    }

    // Possible targets for x and y:
    ll targets_x[2] = {0, n};
    ll targets_y[2] = {0, m};

    ll best_t = -1;
    ll res_x = -1, res_y = -1;

    for (int tx = 0; tx < 2; tx++) {
        for (int ty = 0; ty < 2; ty++) {
            ll Xtarget = targets_x[tx];
            ll Ytarget = targets_y[ty];

            // Solve for x:
            // (x + vx * t) mod (2n) == Xtarget
            // if vx == 0:
            // check if x == Xtarget
            // else solve vx * t ≡ (Xtarget - x) mod 2n

            ll mod_x = 2 * n;
            ll mod_y = 2 * m;

            pair<bool,ll> sol_x, sol_y;

            if (vx == 0) {
                if (x != Xtarget) continue;
                sol_x = {true, 0};
            } else {
                ll b = (Xtarget - x) % mod_x;
                if (b < 0) b += mod_x;
                sol_x = solve_congruence(vx, b, mod_x);
                if (!sol_x.first) continue;
            }

            if (vy == 0) {
                if (y != Ytarget) continue;
                sol_y = {true, 0};
            } else {
                ll b = (Ytarget - y) % mod_y;
                if (b < 0) b += mod_y;
                sol_y = solve_congruence(vy, b, mod_y);
                if (!sol_y.first) continue;
            }

            // Now combine solutions:
            // If both vx and vy zero, ball is stationary, but problem states (vx,vy) != (0,0)
            // If one zero, the solution is t = sol_x or sol_y = 0, so t must satisfy the other congruence.

            if (vx == 0 && vy == 0) continue; // impossible

            if (vx == 0) {
                // t must be sol_y.second + k*mod_y, minimal t >= 0 is sol_y.second
                ll t = sol_y.second;
                if (best_t == -1 || t < best_t) {
                    best_t = t;
                    res_x = Xtarget;
                    res_y = Ytarget;
                }
                continue;
            }

            if (vy == 0) {
                // t must be sol_x.second + k*mod_x, minimal t >= 0 is sol_x.second
                ll t = sol_x.second;
                if (best_t == -1 || t < best_t) {
                    best_t = t;
                    res_x = Xtarget;
                    res_y = Ytarget;
                }
                continue;
            }

            // Both vx and vy != 0
            // Solve CRT for t ≡ sol_x.second mod mod_x
            //               t ≡ sol_y.second mod mod_y

            auto crt_res = crt(sol_x.second, mod_x, sol_y.second, mod_y);
            if (!crt_res.first) continue;
            ll t = crt_res.second.first;
            if (best_t == -1 || t < best_t) {
                best_t = t;
                res_x = Xtarget;
                res_y = Ytarget;
            }
        }
    }

    if (best_t == -1) {
        cout << -1 << "\n";
        return 0;
    }

    cout << res_x << " " << res_y << "\n";

    return 0;
}

