#include <iostream>
#include <vector>
#include <algorithm>
#include <set>

using namespace std;

int n;
vector<vector<int>> cubes;

bool canMakeNumber(const vector<int>& digits) {
    int len = digits.size();
    if (len > n) return false;

    // We need to assign each digit to a distinct cube
    // Try all permutations of cubes for digits
    vector<int> perm(n);
    for (int i = 0; i < n; i++) perm[i] = i;

    do {
        bool ok = true;
        for (int i = 0; i < len; i++) {
            int d = digits[i];
            // Check if cube perm[i] has digit d on any face
            bool found = false;
            for (int f = 0; f < 6; f++) {
                if (cubes[perm[i]][f] == d) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                ok = false;
                break;
            }
        }
        if (ok) return true;
    } while (next_permutation(perm.begin(), perm.end()));

    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    cubes.resize(n, vector<int>(6));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 6; j++) {
            cin >> cubes[i][j];
        }
    }

    // We try numbers from 1 upwards until we find one that can't be made
    int x = 0;
    while (true) {
        x++;
        // Convert x to digits vector
        vector<int> digits;
        int temp = x;
        while (temp > 0) {
            digits.push_back(temp % 10);
            temp /= 10;
        }
        reverse(digits.begin(), digits.end());

        // Leading zero check: digits[0] != 0 guaranteed by construction since x>=1

        if (!canMakeNumber(digits)) {
            cout << x - 1 << "\n";
            break;
        }
    }

    return 0;
}

