#include <iostream>
#include <vector>
using namespace std;

bool checkWin(const vector<string>& board, int r, int c) {
    // Check if placing 'x' at (r,c) creates a line of 3 'x's in a row, column or diagonal
    // Since the board is 4x4, we check all possible triplets that include (r,c)

    // Directions to check: horizontal, vertical, two diagonals
    // For each direction, check all triplets that include (r,c)

    // Horizontal
    for (int start = max(0, c - 2); start <= min(1, c); ++start) {
        int count = 0;
        for (int i = 0; i < 3; ++i) {
            if (board[r][start + i] == 'x') count++;
        }
        if (count == 3) return true;
    }

    // Vertical
    for (int start = max(0, r - 2); start <= min(1, r); ++start) {
        int count = 0;
        for (int i = 0; i < 3; ++i) {
            if (board[start + i][c] == 'x') count++;
        }
        if (count == 3) return true;
    }

    // Diagonal top-left to bottom-right
    // The diagonal containing (r,c) can be identified by r - c
    int diff = r - c;
    // Possible starting points for 3-length diagonal segments on this diagonal
    // The diagonal length can be from 1 to 4, but we only check triplets that include (r,c)
    // The diagonal cells are (i, i - diff) for i in [max(0, diff), min(3, 3+diff)]
    // We try all triplets of length 3 on this diagonal that include (r,c)
    int diagStart = max(0, diff);
    int diagEnd = min(3, 3 + diff);
    for (int start = diagStart; start <= diagEnd - 2; ++start) {
        // Check if (r,c) is in this triplet
        if (r >= start && r <= start + 2 && c >= start - diff && c <= start + 2 - diff) {
            int count = 0;
            for (int i = 0; i < 3; ++i) {
                int rr = start + i;
                int cc = rr - diff;
                if (board[rr][cc] == 'x') count++;
            }
            if (count == 3) return true;
        }
    }

    // Diagonal top-right to bottom-left
    // The diagonal containing (r,c) can be identified by r + c
    int sum = r + c;
    // The diagonal cells are (i, sum - i) for i in [max(0, sum - 3), min(3, sum)]
    int diag2Start = max(0, sum - 3);
    int diag2End = min(3, sum);
    for (int start = diag2Start; start <= diag2End - 2; ++start) {
        // Check if (r,c) is in this triplet
        if (r >= start && r <= start + 2 && c >= sum - (start + 2) && c <= sum - start) {
            int count = 0;
            for (int i = 0; i < 3; ++i) {
                int rr = start + i;
                int cc = sum - rr;
                if (board[rr][cc] == 'x') count++;
            }
            if (count == 3) return true;
        }
    }

    return false;
}

int main() {
    vector<string> board(4);
    for (int i = 0; i < 4; ++i) {
        cin >> board[i];
    }

    for (int r = 0; r < 4; ++r) {
        for (int c = 0; c < 4; ++c) {
            if (board[r][c] == '.') {
                board[r][c] = 'x';
                if (checkWin(board, r, c)) {
                    cout << "YES\n";
                    return 0;
                }
                board[r][c] = '.';
            }
        }
    }

    cout << "NO\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    if (n == 1) {
        cout << "NO\n";
        return 0;
    }

    long long total = 0;
    for (auto x : a) total += x;

    // If total is odd, no equal split possible
    if (total % 2 != 0) {
        cout << "NO\n";
        return 0;
    }

    long long half = total / 2;

    // prefix sums
    vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + a[i];

    // We want to check if after moving one element, we can split into prefix and suffix with equal sums.
    // The split is between positions i and i+1 (1 <= i < n), so prefix sum = half.

    // Let's try to find if there exists a split in the original array:
    // If yes, answer is YES (moving element in same position counts).
    for (int i = 1; i < n; i++) {
        if (pref[i] == half) {
            cout << "YES\n";
            return 0;
        }
    }

    // If not, try moving one element:
    // Idea:
    // For each element a[i], remove it and try to insert it at some position j (0 <= j <= n-1, j != i)
    // After moving, check if there's a split with equal sums.

    // But this is O(n^2), too slow.

    // Optimization:
    // Since total sum is fixed, half is fixed.
    // After removing a[i], sum of remaining elements = total - a[i].
    // After inserting a[i] at position j, the array is rearranged.

    // Let's consider the prefix sums without a[i]:
    // We can precompute prefix sums and suffix sums.

    // Let's try a different approach:

    // We want to find if there exists i,j (positions) such that after moving a[i] to position j,
    // there is a split point k with prefix sum = half.

    // Let's fix the element to move: a[i].
    // Remove a[i], array length n-1.
    // The sum of the array without a[i] is total - a[i].

    // After inserting a[i] at position j, the array length is n again.

    // The prefix sums after moving a[i] can be represented as:
    // prefix sums before insertion + a[i] inserted at position j.

    // Let's try to find a split point k (1 <= k < n) such that prefix sum = half.

    // Let's try to fix the split point k and check if we can move one element to achieve prefix sum = half.

    // Let's precompute prefix sums and suffix sums for the original array.

    // We'll try all split points k (1 <= k < n):
    // For each k, prefix sum is pref[k].

    // We want to find if by moving one element, we can make prefix sum at k equal to half.

    // Let's consider the difference d = half - pref[k].

    // If d == 0, already found (handled above).

    // If d != 0, can we move one element a[i] to change prefix sum at k by d?

    // Moving an element affects prefix sums depending on its original and new positions.

    // Let's analyze:

    // When we remove a[i], prefix sums change:
    // If i < k, prefix sum at k decreases by a[i].
    // If i >= k, prefix sum at k remains the same.

    // When we insert a[i] at position j:
    // If j < k, prefix sum at k increases by a[i].
    // If j >= k, prefix sum at k remains the same.

    // So net change in prefix sum at k after moving a[i] from i to j is:
    // -a[i] if i < k (removal)
    // +a[i] if j < k (insertion)
    // 0 otherwise

    // So net change = (j < k ? a[i] : 0) - (i < k ? a[i] : 0)

    // We want:
    // pref[k] + net_change = half
    // => net_change = half - pref[k] = d

    // So:
    // d = (j < k ? a[i] : 0) - (i < k ? a[i] : 0)

    // Possible values of net_change:
    // Case 1: i < k, j < k
    // net_change = a[i] - a[i] = 0

    // Case 2: i < k, j >= k
    // net_change = 0 - a[i] = -a[i]

    // Case 3: i >= k, j < k
    // net_change = a[i] - 0 = a[i]

    // Case 4: i >= k, j >= k
    // net_change = 0 - 0 = 0

    // So net_change can be 0, a[i], or -a[i].

    // We want net_change = d.

    // So d must be 0, a[i], or -a[i].

    // For each k, we check if d == 0 (already done), or if d == a[i] or d == -a[i] for some i.

    // So for each k:
    // d = half - pref[k]

    // If d == 0 => YES (already done)

    // Else, we want to find i such that:
    // d == a[i] and i >= k (case 3)
    // or d == -a[i] and i < k (case 2)

    // So we need to quickly check if there exists i >= k with a[i] == d
    // or i < k with a[i] == -d

    // We'll build two maps:
    // pos_map: map from value to vector of positions

    unordered_map<long long, vector<int>> pos_map;
    for (int i = 0; i < n; i++) {
        pos_map[a[i]].push_back(i);
    }

    // For each k, check d:
    // Check if d != 0:
    // If d > 0, check if there is i >= k with a[i] == d
    // If d < 0, check if there is i < k with a[i] == -d

    // We'll implement a helper function to check if there exists an index in vector >= or < k.

    auto exists_ge = [](const vector<int>& v, int x) {
        // binary search for first element >= x
        int pos = (int)(std::lower_bound(v.begin(), v.end(), x) - v.begin());
        return pos < (int)v.size();
    };

    auto exists_lt = [](const vector<int>& v, int x) {
        // binary search for first element >= x
        int pos = (int)(std::lower_bound(v.begin(), v.end(), x) - v.begin());
        return pos > 0;
    };

    for (int k = 1; k < n; k++) {
        long long d = half - pref[k];
        if (d == 0) {
            cout << "YES\n";
            return 0;
        }
        if (d > 0) {
            // check i >= k with a[i] == d
            if (pos_map.count(d)) {
                if (exists_ge(pos_map[d], k)) {
                    cout << "YES\n";
                    return 0;
                }
            }
        } else {
            // d < 0
            long long val = -d;
            if (pos_map.count(val)) {
                if (exists_lt(pos_map[val], k)) {
                    cout << "YES\n";
                    return 0;
                }
            }
        }
    }

    cout << "NO\n";
    return 0;
}

