#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    int n; cin >> n;
    string s; cin >> s;

    // Coordinates of keys on the keypad:
    // Layout:
    // 1(0,0) 2(1,0) 3(2,0)
    // 4(0,1) 5(1,1) 6(2,1)
    // 7(0,2) 8(1,2) 9(2,2)
    //    0(1,3)
    pair<int,int> pos[10];
    pos[1] = {0,0};
    pos[2] = {1,0};
    pos[3] = {2,0};
    pos[4] = {0,1};
    pos[5] = {1,1};
    pos[6] = {2,1};
    pos[7] = {0,2};
    pos[8] = {1,2};
    pos[9] = {2,2};
    pos[0] = {1,3};

    // If n == 1, no movements, so no other number can have same movements
    if (n == 1) {
        cout << "YES\n";
        return 0;
    }

    // Calculate the vector movements for the input number
    vector<pair<int,int>> moves;
    for (int i = 1; i < n; i++) {
        int prev = s[i-1] - '0';
        int cur = s[i] - '0';
        moves.push_back({pos[cur].first - pos[prev].first, pos[cur].second - pos[prev].second});
    }

    // Try all other numbers of length n and check if any has the same moves but different number
    // Since n <= 9, brute force is possible (10^9 worst, but we can prune)
    // But 10^9 is too big, so we do a backtracking approach:
    // For each position, try digits 0-9, check if moves match

    // We know the first digit is s[0], so try all digits 0-9 as first digit except s[0]
    // Actually, the first digit can be anything, but to have same moves, the sequence of moves must be same.
    // So we try all possible sequences of length n, and check moves.

    // To optimize, we fix the first digit to all digits 0-9, and backtrack.

    // If we find any number != s with same moves, print NO

    bool found = false;

    // Backtracking function
    // idx: current index in number
    // cur_num: current number being built
    // returns true if found a different number with same moves
    function<bool(int, vector<int>&)> dfs = [&](int idx, vector<int>& cur_num) {
        if (found) return true;
        if (idx == n) {
            // Check if cur_num != s
            bool diff = false;
            for (int i = 0; i < n; i++) {
                if (cur_num[i] != s[i] - '0') {
                    diff = true;
                    break;
                }
            }
            if (!diff) return false; // same number

            // Check moves
            for (int i = 1; i < n; i++) {
                int dx = pos[cur_num[i]].first - pos[cur_num[i-1]].first;
                int dy = pos[cur_num[i]].second - pos[cur_num[i-1]].second;
                if (dx != moves[i-1].first || dy != moves[i-1].second)
                    return false;
            }
            found = true;
            return true;
        }

        for (int d = 0; d <= 9; d++) {
            // Check if move from cur_num[idx-1] to d matches moves[idx-1]
            if (idx == 0) {
                cur_num[idx] = d;
                if (dfs(idx+1, cur_num)) return true;
            } else {
                int dx = pos[d].first - pos[cur_num[idx-1]].first;
                int dy = pos[d].second - pos[cur_num[idx-1]].second;
                if (dx == moves[idx-1].first && dy == moves[idx-1].second) {
                    cur_num[idx] = d;
                    if (dfs(idx+1, cur_num)) return true;
                }
            }
        }
        return false;
    };

    vector<int> cur_num(n);
    dfs(0, cur_num);

    cout << (found ? "NO\n" : "YES\n");

    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, k;
    cin >> n >> k;

    // Maximum messiness is the number of inversions in the reversed sequence:
    // n*(n-1)/2
    long long max_inversions = n * (n - 1) / 2;

    // Each swap can increase the number of inversions by at most n - 1
    // because swapping two elements can fix or create at most n-1 inversions.
    // But the problem states no more than k swaps, so the maximum messiness
    // achievable is min(max_inversions, k * (n - 1))

    // However, the problem's example shows that with k=2 and n=5,
    // the maximum messiness is 10 (which is max_inversions),
    // so the limit is just the max_inversions.

    // Actually, the problem is simpler: the maximum messiness is the number of inversions
    // in the reversed sequence, and we can achieve it by swapping pairs from the ends inward.
    // Each swap can fix multiple inversions, so with k swaps, we can achieve the full reversal
    // if k >= n/2 (since each swap can swap two elements).

    // But the problem states "no more than k swaps", so if k >= n/2, max messiness is max_inversions.
    // Otherwise, the maximum messiness is the number of inversions created by k swaps.

    // Each swap can fix at most (n - 1) inversions, but more precisely,
    // swapping the i-th and (n - i + 1)-th elements creates (n - 2*i + 1) * 2 + 1 inversions.
    // But to keep it simple and efficient, we can just note that each swap can create at most (n - 1) inversions.

    // So the maximum messiness achievable is min(max_inversions, k * (n - 1))

    long long ans = min(max_inversions, k * (n - 1));
    cout << ans << "\n";

    return 0;
}

#include <iostream>
