int main() {
    unsigned long long N, M, K, L;
    cin >> N >> M >> K >> L;

    // If total coins gifted (M * x) > N, impossible because all gifted coins must be distinct
    // Also, L must be <= number of new coins gifted, which is at most M*x - K (new coins = gifted - already owned)
    // So, M*x - K >= L  =>  M*x >= L + K
    // Also, M*x <= N (all gifted coins distinct)
    // So, find minimal x such that:
    // 1) M*x <= N
    // 2) M*x >= L + K

    // If L + K > N, impossible
    if (L + K > N) {
        cout << -1 << "\n";
        return 0;
    }

    // minimal x satisfying M*x >= L + K
    unsigned long long x = (L + K + M - 1) / M;

    // check if M*x <= N
    if (M > 0 && x <= N / M) {
        cout << x << "\n";
    } else {
        cout << -1 << "\n";
    }

    return 0;
}

