    int min_row = n, max_row = -1, min_col = m, max_col = -1;
    int black_cells = 0;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[i][j] == 'B') {
                black_cells++;
                min_row = min(min_row, i);
                max_row = max(max_row, i);
                min_col = min(min_col, j);
                max_col = max(max_col, j);
            }
        }
    }

    if (black_cells == 0) {
        // No black cells, paint one cell black
        cout << 1 << "\n";
        return 0;
    }

    int height = max_row - min_row + 1;
    int width = max_col - min_col + 1;

    int side = max(height, width);

    if (side > n || side > m) {
        cout << -1 << "\n";
        return 0;
    }

    // Check if the black cells fit inside a square of side 'side'
    // The square must cover all black cells, so it must at least cover from min_row to max_row and min_col to max_col
    // We try to place the square so that it covers all black cells and is inside the grid

    // The square's top-left corner row can be from max(0, max_row - side + 1) to min(min_row, n - side)
    // Similarly for columns

    int row_start_min = max(0, max_row - side + 1);
    int row_start_max = min(min_row, n - side);
    int col_start_min = max(0, max_col - side + 1);
    int col_start_max = min(min_col, m - side);

    bool possible = false;
    int min_paint = -1;

    for (int r = row_start_min; r <= row_start_max; r++) {
        for (int c = col_start_min; c <= col_start_max; c++) {
            // Check if all black cells are inside the square [r, r+side-1] x [c, c+side-1]
            // Since we chose r and c to cover all black cells, this should be true

            // Count how many white cells inside the square need to be painted black
            int paint = 0;
            bool valid = true;

            for (int i = r; i < r + side; i++) {
                for (int j = c; j < c + side; j++) {
                    if (grid[i][j] == 'W') {
                        paint++;
                    }
                }
            }

            // Check if any black cell lies outside the square (should not happen due to r,c ranges)
            // But let's verify to be safe
            for (int i = 0; i < n && valid; i++) {
                for (int j = 0; j < m && valid; j++) {
                    if (grid[i][j] == 'B') {
                        if (i < r || i >= r + side || j < c || j >= c + side) {
                            valid = false;
                        }
                    }
                }
            }

            if (valid) {
                if (min_paint == -1 || paint < min_paint) {
                    min_paint = paint;
                    possible = true;
                }
            }
        }
    }

    cout << (possible ? min_paint : -1) << "\n";

    return 0;
}

