const int MOD = 1000000007;

long long modpow(long long base, long long exp, int mod) {
    long long result = 1 % mod;
    long long cur = base % mod;
    while (exp > 0) {
        if (exp & 1) result = (result * cur) % mod;
        cur = (cur * cur) % mod;
        exp >>= 1;
    }
    return result;
}

