    // Compute 2^m mod MOD
    long long two_pow_m = modpow(2, m, MOD);
    long long base = (two_pow_m - 1 + MOD) % MOD;
    long long ans = modpow(base, n, MOD);

    cout << ans << "\n";

    return 0;
}

