const int MAXN = 500;

int n, m;
vector<int> adj[MAXN + 1];
vector<pair<int,int>> edges;

enum State { UNVISITED, VISITING, VISITED };
State state[MAXN + 1];
int cycle_start = -1, cycle_end = -1;
vector<int> cycle_nodes;
vector<int> cycle_edges_indices;

bool dfs(int u, int parent_edge_idx = -1) {
    state[u] = VISITING;
    for (int i = 0; i < (int)adj[u].size(); i++) {
        int v = adj[u][i];
        int edge_idx = -1;
        // find edge index from edges vector
        // edges are stored in order, so we can map from u->v
        // but to avoid O(m) search, we store edges in edges vector and keep track of indices
        // We'll store edges in edges vector and keep a map from (u,v) to index
        // But since edges vector is in input order, we can store edge indices in adjacency list as well
        // Let's do that now: we need to store edge indices in adjacency list
    }
    state[u] = VISITED;
    return false;
}

// To fix above, we need to store edge indices in adjacency list
// Let's redefine adjacency list as vector of pairs (neighbor, edge_index)

vector<pair<int,int>> adj2[MAXN + 1];

bool dfs_cycle(int u, vector<int>& parent_edge) {
    state[u] = VISITING;
    for (auto& p : adj2[u]) {
        int v = p.first;
        int eidx = p.second;
        if (state[v] == UNVISITED) {
            parent_edge[v] = eidx;
            if (dfs_cycle(v, parent_edge))
                return true;
        } else if (state[v] == VISITING) {
            // cycle found
            cycle_start = v;
            cycle_end = u;
            parent_edge[v] = eidx; // store edge that leads to cycle start
            return true;
        }
    }
    state[u] = VISITED;
    return false;
}

bool has_cycle() {
    fill(state, state + n + 1, UNVISITED);
    vector<int> parent_edge(n + 1, -1);
    cycle_start = -1;
    cycle_end = -1;
    for (int i = 1; i <= n; i++) {
        if (state[i] == UNVISITED) {
            if (dfs_cycle(i, parent_edge)) {
                // reconstruct cycle edges
                cycle_edges_indices.clear();
                int cur = cycle_end;
                cycle_edges_indices.push_back(parent_edge[cur]);
                while (cur != cycle_start) {
                    // find the edge that leads to cur
                    int e = parent_edge[cur];
                    // edge e goes from some node to cur
                    // find the from node of edge e
                    int from = edges[e].first;
                    cur = from;
                    cycle_edges_indices.push_back(parent_edge[cur]);
                }
                // cycle_edges_indices contains one extra edge at the end (parent_edge[cycle_start])
                // remove the last -1 if present
                cycle_edges_indices.pop_back();
                return true;
            }
        }
    }
    return false;
}

bool check_acyclic_after_removal(int remove_edge_idx) {
    // Build graph without edge remove_edge_idx
    for (int i = 1; i <= n; i++) {
        state[i] = UNVISITED;
    }
    // We'll do a DFS to detect cycle ignoring remove_edge_idx
    // Use a stack or recursion with state array
    // We'll do a DFS with cycle detection

    function<bool(int)> dfs_check = [&](int u) {
        state[u] = VISITING;
        for (auto& p : adj2[u]) {
            int v = p.first;
            int eidx = p.second;
            if (eidx == remove_edge_idx) continue;
            if (state[v] == UNVISITED) {
                if (dfs_check(v)) return true;
            } else if (state[v] == VISITING) {
                return true;
            }
        }
        state[u] = VISITED;
        return false;
    };

    for (int i = 1; i <= n; i++) {
        if (state[i] == UNVISITED) {
            if (dfs_check(i)) return false;
        }
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;
    edges.resize(m);
    for (int i = 0; i < m; i++) {
        int u,v; cin >> u >> v;
        edges[i] = {u,v};
        adj2[u].emplace_back(v,i);
    }

    if (!has_cycle()) {
        // no cycle, already acyclic
        cout << "YES\n";
        return 0;
    }

    // try removing each edge in the cycle
    for (int eidx : cycle_edges_indices) {
        if (check_acyclic_after_removal(eidx)) {
            cout << "YES\n";
            return 0;
        }
    }

    cout << "NO\n";
    return 0;
}

