    vector<long long> c(n);
    for (int i = 0; i < n; i++) cin >> c[i];

    // Make sure cost is non-increasing when doubling volume
    for (int i = 1; i < n; i++) {
        c[i] = min(c[i], 2 * c[i - 1]);
    }
    // Also propagate backwards to ensure minimal cost for smaller bottles
    for (int i = n - 2; i >= 0; i--) {
        c[i] = min(c[i], c[i + 1]);
    }

    long long ans = LLONG_MAX;
    long long cost = 0;
    long long volume = 0;

    for (int i = n - 1; i >= 0; i--) {
        long long bottle_volume = (1LL << (i + 1)) - 1;
        long long need = (L - volume + bottle_volume - 1) / bottle_volume;
        cost += need * c[i];
        volume += need * bottle_volume;
        ans = min(ans, cost);
    }

    cout << ans << "\n";

    return 0;
}

