        xpowers.push_back(val);
        if (x != 1) {
            while (true) {
                if (val > r / x) break;
                val *= x;
                xpowers.push_back(val);
            }
        }
    }

    // Generate powers of y up to r
    {
        uint64_t val = 1;
        ypowers.push_back(val);
        if (y != 1) {
            while (true) {
                if (val > r / y) break;
                val *= y;
                ypowers.push_back(val);
            }
        }
    }

    set<uint64_t> unlucky;

    for (auto a : xpowers) {
        for (auto b : ypowers) {
            uint64_t sum = a + b;
            if (sum >= l && sum <= r) {
                unlucky.insert(sum);
            }
            if (sum > r) break;
        }
    }

    if (unlucky.empty()) {
        // No unlucky years in [l, r], so whole interval is golden age
        cout << r - l + 1 << "\n";
        return 0;
    }

    // Add boundaries to simplify calculation
    // We'll consider intervals between unlucky years and edges l-1 and r+1
    vector<uint64_t> points;
