#include <iostream>
#include <cmath>

using namespace std;

int main() {
    long long n;
    cin >> n;

    // Function to find the maximum divisor of x (not equal to x)
    auto max_divisor = [](long long x) -> long long {
        for (long long i = (long long) sqrt(x); i >= 1; --i) {
            if (x % i == 0) {
                if (i != x && i >= 2) return x / i;
                long long d = x / i;
                if (d != x && d >= 2) return d;
            }
        }
        return 1; // fallback, for prime numbers max divisor is 1
    };

    // If n is prime, the only way is to pay tax on n itself (which is n's max divisor = 1)
    // But we can split n into parts >= 2, so we try to split n into k parts of 2 or more
    // The minimal tax is achieved by splitting into parts of equal size with minimal max divisor sum.

    // The problem reduces to:
    // If n is prime, minimal tax is 1 * n/2 (if n even) or something else?
    // But from problem statement and examples, the minimal tax is the minimal max divisor sum of parts.

    // Actually, the minimal tax is the minimal sum of max divisors of parts >= 2 summing to n.

    // Observation:
    // The minimal tax is the minimal max divisor of any part times number of parts.
    // Since max divisor of a prime is 1, splitting into parts of size 2 (max divisor 1) is best.

    // So, minimal tax = minimal max divisor * number of parts
    // minimal max divisor is 1 (for prime parts)
    // number of parts = n / 2 (if n even)
    // if n odd, we can have one part 3 (max divisor 1) and rest parts 2 (max divisor 1)
    // So minimal tax = n / 2 (floor) + (n % 2) * 1

    // But the problem states that the tax for a part is the maximum divisor of that part (not equal to itself).
    // For 2, max divisor is 1
    // For 3, max divisor is 1
    // For 4, max divisor is 2
    // So splitting into parts of 2 or 3 is best.

    // So minimal tax = number_of_parts * 1 = number_of_parts
    // number_of_parts = n / 2 (if even)
    // if odd, number_of_parts = n/2 (floor) + 1

    // But the problem examples show:
    // Input: 4 -> Output: 2 (splitting into two parts of 2, each tax 1, total 2)
    // Input: 27 -> Output: 3 (splitting into three parts of 9, each tax 3, total 9)
    // So the above reasoning is wrong.

    // Let's try to find the minimal tax by splitting into parts all equal to the minimal prime factor of n.

    // So the minimal tax is minimal prime factor of n.

    // If n is prime, minimal tax is 1 * n/2 (if n even) or something else?

    // Let's find minimal prime factor of n.

    long long minimal_prime_factor = 0;
    for (long long i = 2; i <= (long long) sqrt(n); ++i) {
        if (n % i == 0) {
            minimal_prime_factor = i;
            break;
        }
    }

    if (minimal_prime_factor == 0) {
        // n is prime
        cout << 1 << "\n";
    } else {
        cout << n / minimal_prime_factor << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

bool isVowel(char c) {
    return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s; cin >> s;
    int n = (int)s.size();

    // dp[i] = minimal number of spaces inserted to split s[0..i-1]
    // parent[i] = where the last word starts
    vector<int> dp(n + 1, INT_MAX);
    vector<int> parent(n + 1, -1);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        // try all possible previous splits j < i
        // check if s[j..i-1] is typo-free
        for (int j = i - 1; j >= 0; j--) {
            // check s[j..i-1]
            int length = i - j;
            if (length < 3) {
                // no typo possible if length < 3
                if (dp[j] != INT_MAX && dp[j] < dp[i]) {
                    dp[i] = dp[j];
                    parent[i] = j;
                }
                continue;
            }

            // check for typo in s[j..i-1]
            // typo if there is a block of >=3 consonants with at least two different letters
            // We only need to check the entire substring s[j..i-1] for such blocks
            // But since we want to be efficient, we can check the substring once

            // We'll scan s[j..i-1] to find any block of >=3 consonants with at least two different letters
            bool typo = false;
            int cons_start = -1;
            for (int k = j; k < i; k++) {
                if (!isVowel(s[k])) {
                    if (cons_start == -1) cons_start = k;
                } else {
                    if (cons_start != -1) {
                        int cons_len = k - cons_start;
                        if (cons_len >= 3) {
                            // check if all letters same
                            char c = s[cons_start];
                            bool all_same = true;
                            for (int x = cons_start + 1; x < k; x++) {
                                if (s[x] != c) {
                                    all_same = false;
                                    break;
                                }
                            }
                            if (!all_same) {
                                typo = true;
                                break;
                            }
                        }
                        cons_start = -1;
                    }
                }
            }
            // check last block if ended at i-1
            if (!typo && cons_start != -1) {
                int cons_len = i - cons_start;
                if (cons_len >= 3) {
                    char c = s[cons_start];
                    bool all_same = true;
                    for (int x = cons_start + 1; x < i; x++) {
                        if (s[x] != c) {
                            all_same = false;
                            break;
                        }
                    }
                    if (!all_same) {
                        typo = true;
                    }
                }
            }

            if (!typo && dp[j] != INT_MAX) {
                int cost = dp[j] + (j == 0 ? 0 : 1);
                if (cost < dp[i]) {
                    dp[i] = cost;
                    parent[i] = j;
                }
            }
        }
    }

    if (dp[n] == 0) {
        // no spaces needed
        cout << s << "\n";
        return 0;
    }

    // reconstruct answer
    vector<string> words;
    int cur = n;
    while (cur > 0) {
        int st = parent[cur];
        words.push_back(s.substr(st, cur - st));
        cur = st;
    }
    reverse(words.begin(), words.end());

    for (auto &w : words) cout << w << " ";
    cout << "\n";

    return 0;
}

