        long long cost1 = b[i];
        if (cost1 > s) continue;
        long long rem = s - cost1;

        // binary search on d to find max j with d[j] <= rem
        int pos = upper_bound(d.begin(), d.end(), rem) - d.begin() - 1;
        if (pos < 0) pos = 0;

        long long instant = c[pos];
        if (instant > n) instant = n;

        long long need = n - instant;
        if (need < 0) need = 0;

        long long time = need * a[i];
        if (time < ans) ans = time;
    }

    cout << ans << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    long long M;
    cin >> n >> k >> M;
    vector<long long> t(k);
    for (int i = 0; i < k; i++) cin >> t[i];

    sort(t.begin(), t.end());

    // prefix sums of times for subtasks 1..j
    vector<long long> prefix(k + 1, 0);
    for (int i = 1; i <= k; i++) {
        prefix[i] = prefix[i - 1] + t[i - 1];
    }

    long long ans = 0;
    // Try to complete x tasks fully (0 <= x <= n)
    // For each x, time spent = x * sum of all subtasks
    // Remaining time can be used to solve subtasks partially on other tasks
    for (int x = 0; x <= n; x++) {
        long long time_used = prefix[k] * x;
        if (time_used > M) break;

        long long rem = M - time_used;
        // number of tasks left to partially solve
        int left = n - x;

        // We want to maximize points from partial subtasks on left tasks
        // For each subtask j (from 1 to k-1), time to solve it on one task is t_j
        // We can solve subtasks in any order, so solve cheapest subtasks first
        // But since subtasks times are sorted ascending, we can try all j from 0 to k-1
        // For each j, time to solve j subtasks on one task = prefix[j]
        // total time for left tasks = left * prefix[j]
        // We want max j such that left * prefix[j] <= rem

        // Binary search for max j
        int low = 0, high = k;
        while (low < high) {
            int mid = (low + high + 1) / 2;
            if (left * prefix[mid] <= rem) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }

        // points = x*(k+1) + left*low
        long long points = (long long)x * (k + 1) + (long long)left * low;
        if (points > ans) ans = points;
    }

    cout << ans << "\n";

    return 0;
}

#include <iostream>
