int main() {
    long long n, m, k;
    cin >> n >> m >> k;

    if (k < n - 1) {
        // Moving down the first column
        cout << (1 + k) << " 1\n";
        return 0;
    }

    k -= (n - 1);
    long long cycle_len = 2 * (m - 1);
    long long cycle_num = k / cycle_len;
    long long pos_in_cycle = k % cycle_len;

    long long col = 2 + cycle_num;
    long long row;

    if (pos_in_cycle < m - 1) {
        // moving right on current row
        row = n - cycle_num;
        col += pos_in_cycle;
    } else {
        // moving left on row above
        row = n - cycle_num - 1;
        col += (cycle_len - 1 - pos_in_cycle);
    }

    cout << row << " " << col << "\n";
    return 0;
}

