int main() {
    unsigned long long b, d, s;
    cin >> b >> d >> s;

    // The minimal number of missed meals is:
    // total meals in the interval - (b + d + s)
    // We try all possible arrival and departure times (4 options each):
    // arrival: before breakfast(0), before dinner(1), before supper(2), after supper(3)
    // departure: before breakfast(0), before dinner(1), before supper(2), after supper(3)
    // For each pair, calculate the minimal number of days needed to cover the meals,
    // then calculate total meals in that interval and subtract the eaten meals.

    // Meals per day: breakfast(0), dinner(1), supper(2)
    // The order is breakfast -> dinner -> supper

    // We'll represent arrival and departure times as integers 0..3:
    // 0 - before breakfast
    // 1 - before dinner
    // 2 - before supper
    // 3 - after supper

    // For each arrival and departure time, calculate minimal days needed to cover b,d,s
    // and total meals in that interval.

    // Helper lambda to calculate meals count in a partial day from start to end time
    auto meals_in_partial_day = [](int start, int end) -> int {
        // start and end in [0..3], start <= end
        // meals are at times 0 (breakfast),1(dinner),2(supper)
        // count how many meals are in [start,end)
        int count = 0;
        for (int meal = 0; meal < 3; meal++) {
            if (meal >= start && meal < end) count++;
        }
        return count;
    };

    unsigned long long ans = ULLONG_MAX;

    for (int arr = 0; arr <= 3; arr++) {
        for (int dep = arr; dep <= 3; dep++) {
            // We consider intervals starting at arr and ending at dep on the same day
            // or spanning multiple days.

            // The minimal number of days needed to cover b,d,s depends on how many meals
            // are available in the first partial day (from arr to 3) and last partial day (from 0 to dep),
            // and full days in between.

            // Number of meals in first partial day:
            int first_day_meals = 0;
            for (int meal = arr; meal < 3; meal++) {
                first_day_meals++;
            }
            // Number of meals in last partial day:
            int last_day_meals = 0;
            for (int meal = 0; meal < dep; meal++) {
                last_day_meals++;
            }

            // If arr == dep and interval is within one day:
            if (arr == dep) {
                // Interval length is zero, no meals possible
                // But Vasiliy could have arrived and left at the same time, so no meals
                // But since b+d+s >=1, this is invalid
                // So skip
                continue;
            }

            // Total meals in one day:
            const unsigned long long meals_per_day = 3;

            // We try all possible number of days >=1
            // For each number of days, total meals in interval is:
            // first_day_meals + (days-2)*3 + last_day_meals if days >=2
            // if days ==1, total meals = meals_in_partial_day(arr, dep)

            // We want minimal missed meals = total meals in interval - (b+d+s) >=0

            // Let's find minimal days needed to cover b,d,s

            // The minimal number of days needed to cover b breakfasts:
            // Each full day has 1 breakfast, plus possibly breakfast in first or last partial day
            // But breakfasts only occur once per day at meal 0

            // Similarly for dinners and suppers.

            // Let's define functions to calculate minimal days needed for each meal type.

            // For breakfasts:
            // breakfasts per full day = 1
            // breakfasts in first partial day = 1 if arr <= 0 < 3 else 0
            // breakfasts in last partial day = 1 if 0 < dep else 0

            int first_breakfast = (arr <= 0 && 0 < 3) ? 1 : 0;
            int last_breakfast = (0 < dep) ? 1 : 0;

            // For dinners (meal 1):
            int first_dinner = (arr <= 1 && 1 < 3) ? 1 : 0;
            int last_dinner = (1 < dep) ? 1 : 0;

            // For suppers (meal 2):
            int first_supper = (arr <= 2 && 2 < 3) ? 1 : 0;
            int last_supper = (2 < dep) ? 1 : 0;

            // For each meal type, minimal days needed:
            // days_needed = max(1, ceil((count - first_partial - last_partial)/1) + (first_partial + last_partial > 0 ? 2 : 1))
            // But better to try days from 1 to some max and check feasibility.

            // Since b,d,s can be up to 1e18, we can't iterate days.

            // Let's define a function to check if for given days, the meals can be covered.

            auto can_cover = [&](unsigned long long days) -> bool {
                if (days == 0) return false;
                // total breakfasts available:
                unsigned long long total_breakfasts = 0;
                if (days == 1) {
                    // only partial day from arr to dep
                    total_breakfasts = (arr <= 0 && 0 < dep) ? 1 : 0;
                } else {
                    // first partial day + last partial day + full days in between
                    total_breakfasts = first_breakfast + last_breakfast + (days - 2);
                }
                if (total_breakfasts < b) return false;

                unsigned long long total_dinners = 0;
                if (days == 1) {
                    total_dinners = (arr <= 1 && 1 < dep) ? 1 : 0;
                } else {
                    total_dinners = first_dinner + last_dinner + (days - 2);
                }
                if (total_dinners < d) return false;

                unsigned long long total_suppers = 0;
                if (days == 1) {
                    total_suppers = (arr <= 2 && 2 < dep) ? 1 : 0;
                } else {
                    total_suppers = first_supper + last_supper + (days - 2);
                }
                if (total_suppers < s) return false;

                return true;
            };

            // Binary search minimal days
            unsigned long long left = 1, right = 1000000000000000000ULL;
            while (left < right) {
                unsigned long long mid = left + (right - left) / 2;
                if (can_cover(mid)) right = mid;
                else left = mid + 1;
            }
            unsigned long long days = left;

            // Calculate total meals in interval:
            unsigned long long total_meals = 0;
            if (days == 1) {
                // meals in partial day from arr to dep
                total_meals = 0;
                for (int meal = 0; meal < 3; meal++) {
                    if (meal >= arr && meal < dep) total_meals++;
                }
            } else {
                total_meals = first_breakfast + first_dinner + first_supper
                            + last_breakfast + last_dinner + last_supper
                            + (days - 2) * 3;
            }

            if (total_meals < b + d + s) continue; // invalid, can't have less meals than eaten

            unsigned long long missed = total_meals - (b + d + s);
            if (missed < ans) ans = missed;
        }
    }

    cout << ans << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    if (n == 1) {
        // Any x,y with x*y >= a[0] works, just print YES and a[0],1
        cout << "YES\n" << a[0] << " 1\n";
        return 0;
    }

    // We want to find x,y such that:
    // For each a_i, position is (row_i, col_i) with:
    // row_i = (a_i - 1) / y + 1
    // col_i = (a_i - 1) % y + 1
    //
    // Moves are allowed only between adjacent cells (up/down/left/right)
    // So for each consecutive pair (a_i, a_{i+1}), the Manhattan distance between their positions must be 1:
    // |row_i - row_{i+1}| + |col_i - col_{i+1}| = 1
    //
    // We don't know x,y but we know x*y >= max(a_i)
    //
    // We try to find y by analyzing the differences between consecutive a_i.
    // For each pair, the difference d = |a_{i+1} - a_i|
    // If d == 1, then the move is horizontal (col changes by 1)
    // If d != 1, then the move is vertical (row changes by 1)
    //
    // For vertical moves:
    // |row_i - row_{i+1}| = 1
    // row_i = (a_i - 1)/y + 1
    // row_{i+1} = (a_{i+1} - 1)/y + 1
    // So |(a_i - 1)/y - (a_{i+1} - 1)/y| = 1
    // => |(a_i - 1) - (a_{i+1} - 1)| / y = 1
    // => |a_i - a_{i+1}| / y = 1
    // => y = |a_i - a_{i+1}|
    //
    // So for vertical moves, y must be equal to the difference.
    //
    // For horizontal moves, difference is 1, so no restriction on y.
    //
    // So all vertical moves must have the same difference y.
    //
    // We find all vertical moves and check if their differences are equal.
    // If not, print NO.
    //
    // Then check if the path is valid for that y.
    //
    // Also, x = ceil(max(a_i)/y)
    // Check if x,y <= 1e9

    long long y = 0;
    for (int i = 0; i + 1 < n; i++) {
        long long diff = abs(a[i+1] - a[i]);
        if (diff == 1) continue; // horizontal move, no restriction
        if (y == 0) y = diff;
        else if (y != diff) {
            cout << "NO\n";
            return 0;
        }
    }

    if (y == 0) {
        // No vertical moves, so y can be any number >= max(a_i)
        // Just pick y = max(a_i)
        y = *max_element(a.begin(), a.end());
        if (y > 1000000000) {
            cout << "NO\n";
            return 0;
        }
        long long x = 1;
        cout << "YES\n" << x << " " << y << "\n";
        return 0;
    }

    // Check if y > 1e9
    if (y > 1000000000) {
        cout << "NO\n";
        return 0;
    }

    // Compute x = ceil(max(a_i)/y)
    long long maxA = *max_element(a.begin(), a.end());
    long long x = (maxA + y - 1) / y;
    if (x > 1000000000) {
        cout << "NO\n";
        return 0;
    }

    // Now verify the path with this x,y
    // For each consecutive pair:
    // compute positions:
    // row_i = (a_i - 1)/y + 1
    // col_i = (a_i - 1)%y + 1
    // check manhattan distance == 1

    for (int i = 0; i + 1 < n; i++) {
        long long r1 = (a[i] - 1) / y + 1;
        long long c1 = (a[i] - 1) % y + 1;
        long long r2 = (a[i+1] - 1) / y + 1;
        long long c2 = (a[i+1] - 1) % y + 1;
        long long dist = abs(r1 - r2) + abs(c1 - c2);
        if (dist != 1) {
            cout << "NO\n";
            return 0;
        }
    }

    cout << "YES\n" << x << " " << y << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string a, b;
    cin >> a >> b;
    int n = (int)a.size(), m = (int)b.size();

    // prefix[i] = the maximum prefix of b[0..i-1] that is subsequence of a
    vector<int> prefix(m + 1, -1);
    prefix[0] = 0;
    int pos = 0;
    for (int i = 0; i < m; i++) {
        if (prefix[i] == -1) continue;
        // try to match b[i] in a starting from prefix[i]
        while (pos < n && a[pos] != b[i]) pos++;
        if (pos < n) {
            prefix[i + 1] = pos + 1;
            pos++;
        }
    }

    // suffix[i] = the minimum position in a where b[i..m-1] can start as subsequence
    vector<int> suffix(m + 1, n + 1);
    suffix[m] = n;
    pos = n - 1;
    for (int i = m - 1; i >= 0; i--) {
        if (suffix[i + 1] == n + 1) continue;
        // try to match b[i] in a backwards starting from suffix[i+1]-1
        while (pos >= 0 && a[pos] != b[i]) pos--;
        if (pos >= 0) {
            suffix[i] = pos;
            pos--;
        }
    }

    // We want to remove a consecutive substring b[l..r-1]
    // so the resulting subsequence is b[0..l-1] + b[r..m-1]
    // prefix[l] gives position in a after matching b[0..l-1]
    // suffix[r] gives position in a where b[r..m-1] starts
    // We want prefix[l] <= suffix[r] to merge subsequences

    int best_len = -1;
    int best_l = 0, best_r = 0;

    // Try all splits
    for (int l = 0; l <= m; l++) {
        // prefix[l] must be valid
        if (prefix[l] == -1) continue;

        // binary search for r >= l with suffix[r] >= prefix[l]
        int low = l, high = m;
        while (low < high) {
            int mid = (low + high) / 2;
            if (suffix[mid] >= prefix[l]) high = mid;
            else low = mid + 1;
        }
        int r = low;
        if (r <= m && suffix[r] >= prefix[l]) {
            int len = (l) + (m - r);
            if (len > best_len) {
                best_len = len;
                best_l = l;
                best_r = r;
            }
        }
    }

    if (best_len <= 0) {
        cout << "-\n";
        return 0;
    }

    // print b[0..best_l-1] + b[best_r..m-1]
    for (int i = 0; i < best_l; i++) cout << b[i];
    for (int i = best_r; i < m; i++) cout << b[i];
    cout << "\n";

    return 0;
}

