#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    long long n, a, b, c;
    cin >> n >> a >> b >> c;

    // If plastic bottle is cheaper or equal to glass bottle after return, buy only plastic
    if (a <= b - c) {
        cout << n / a << "\n";
        return 0;
    }

    // Otherwise, try to buy glass bottles first, return them, and then buy plastic bottles with the refunded money
    // Each glass bottle effectively costs (b - c) rubles after return
    long long max_liters = 0;

    // Max glass bottles we can buy initially
    long long max_glass = n / b;

    // Try all possible numbers of glass bottles to buy initially (from 0 to max_glass)
    // For each, calculate total liters = glass bottles + plastic bottles bought with leftover + refund
    // Since n can be large, we try only a few candidates around max_glass to optimize
    // But since max_glass can be large, we try only max_glass and max_glass-1 to cover edge cases

    for (long long glass = max(0LL, max_glass - 2); glass <= max_glass; ++glass) {
        if (glass < 0) continue;
        if (glass * b > n) continue;

        long long money_left = n - glass * b + glass * c;
        long long plastic = money_left / a;
        long long total = glass + plastic;
        if (total > max_liters) max_liters = total;
    }

    cout << max_liters << "\n";
    return 0;
}

