#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    // If n == 1:
    // The expression is just a_1.
    // It is false only if a_1 == 0.
    if (n == 1) {
        if (a[0] == 0) {
            cout << "YES\n0\n";
        } else {
            cout << "NO\n";
        }
        return 0;
    }

    // To get false result, the top-level implication must be:
    // true -> false = 0
    // So the left side must be true, right side false.

    // We want to find a way to bracket so that the whole expression evaluates to 0.

    // Key observations:
    // - The only way to get 0 is (true -> false).
    // - So the expression must be split into two parts:
    //   left_expr -> right_expr
    //   with left_expr == 1 and right_expr == 0.

    // We can try to find a partition i (1 <= i < n) such that:
    // left_expr = a_1 -> a_2 -> ... -> a_i  evaluates to 1 (true)
    // right_expr = a_{i+1} -> ... -> a_n evaluates to 0 (false)

    // Because we can put brackets arbitrarily, we can recursively apply the same logic.

    // But the problem is large (up to 1e5), so we need an O(n) solution.

    // Let's analyze the evaluation of left-to-right implication without brackets:
    // The left-to-right evaluation is:
    // res = a_1
    // for i=2 to n:
    //   res = (res -> a_i)
    // where (x->y) = !x || y

    // Let's precompute prefix evaluations from left to right without brackets:
    // prefix[i] = value of a_1 -> a_2 -> ... -> a_i (left to right)
    vector<int> prefix(n);
    prefix[0] = a[0];
    for (int i = 1; i < n; i++) {
        prefix[i] = (!prefix[i-1]) || a[i];
    }

    // Similarly, we want to find a suffix that can be bracketed to 0.
    // But suffix evaluation is not straightforward because of brackets.

    // However, the problem states that with brackets, evaluation order can be changed.

    // Let's consider the minimal expression that evaluates to 0:
    // It must be (true -> false).

    // So the right part must evaluate to 0.
    // For a single argument, only 0 evaluates to 0.
    // For multiple arguments, we can try to bracket to get 0.

    // Let's try to find the rightmost 0 in the array.
    // Because the right side must be false, and false can only be obtained if the expression evaluates to 0.

    // Let's try to find an index i (1 <= i < n) such that:
    // prefix[i-1] == 1 (left side true)
    // and the suffix starting at i can be bracketed to 0.

    // For suffix, if it is a single 0, then suffix evaluates to 0.
    // For multiple elements, can we bracket to 0?

    // Let's analyze suffixes:

    // If suffix length == 1:
    //   suffix evaluates to a[i]
    //   so if a[i] == 0, suffix evaluates to 0.

    // If suffix length > 1:
    //   Can we bracket to get 0?

    // Let's try to find a suffix that can be bracketed to 0.

    // Let's define a function canBeFalse(l, r) that returns true if the subexpression a_l..a_r can be bracketed to 0.

    // Base case:
    // if l == r:
    //   return a[l] == 0

    // For longer expressions:
    // We want to find a split k (l <= k < r) such that:
    // left_expr = a_l..a_k evaluates to 1
    // right_expr = a_{k+1}..a_r evaluates to 0
    // then (left_expr -> right_expr) = 0

    // So we can use DP to find canBeFalse(l,r).

    // But n can be up to 1e5, so O(n^2) is impossible.

    // Let's try to find a pattern.

    // Let's check if the suffix can be bracketed to 0.

    // Let's try to find the rightmost 0 in the array.

    // If there is no 0 in the array, answer is NO.

    // If there is at least one 0, then:

    // Let's try to put brackets so that the rightmost 0 is the rightmost argument in the right subexpression.

    // Let's try to split at i = position of rightmost 0.

    // Then:
    // left_expr = a_1..a_{i-1}
    // right_expr = a_i..a_n

    // We want left_expr to evaluate to 1 (true) and right_expr to evaluate to 0 (false).

    // For right_expr:
    // If right_expr is a single 0, then it evaluates to 0.

    // If right_expr length > 1, can it be bracketed to 0?

    // Let's check if right_expr can be bracketed to 0.

    // Let's try to bracket right_expr as (a_i -> (a_{i+1} -> (... (a_{n-1} -> a_n)...)))

    // Because implication is right-associative with brackets, the rightmost evaluation is:

    // Let's evaluate right_expr right-associative:

    // Let's define a function to evaluate right-associative implication:

    // For right-associative:
    // val = a_n
    // for j = n-1 down to i:
    //   val = a_j -> val = (!a_j) || val

    // If this value is 0, then right_expr can be bracketed to 0.

    // So we can precompute suffix evaluations right-associative.

    // Let's do that.

    vector<int> suffix(n);
    suffix[n-1] = a[n-1];
    for (int i = n - 2; i >= 0; i--) {
        suffix[i] = (!a[i]) || suffix[i+1];
    }

    // Now, for each position i (1 <= i < n), check if:
    // prefix[i-1] == 1 and suffix[i] == 0

    // If yes, then we can split expression as:
    // (left_expr) -> (right_expr)
    // where left_expr = a_1..a_{i-1} evaluated left-to-right (no brackets needed)
    // right_expr = a_i..a_n evaluated right-associative (bracketed as right-associative)

    // We need to print the expression with brackets.

    // If no such i exists, print NO.

    // If n == 1 and a[0] == 0, print YES and 0.

    // Otherwise, try to find i.

    int split = -1;
    for (int i = 1; i < n; i++) {
        if (prefix[i-1] == 1 && suffix[i] == 0) {
            split = i;
            break;
        }
    }

    if (split == -1) {
        // No split found
        // Check if n == 1 and a[0] == 0 handled above
        cout << "NO\n";
        return 0;
    }

    cout << "YES\n";

    // Now print expression:
    // left_expr: a_0..a_{split-1} evaluated left-to-right without extra brackets
    // right_expr: a_{split}..a_{n-1} evaluated right-associative with brackets

    // For left_expr, we can print as:
    // a_0->a_1->...->a_{split-1} without brackets (since left-to-right)

    // For right_expr, we print with brackets to enforce right-associative:
    // a_{split} -> (a_{split+1} -> (... (a_{n-2} -> a_{n-1})...))

    // To print right_expr with brackets, we can recursively print:
    // if length == 1: print a[i]
    // else print (a[i]->right_expr)

    // Let's implement printing functions.

    auto print_left = [&](int l, int r) {
        // print a_l->a_{l+1}->...->a_r without brackets
        for (int i = l; i <= r; i++) {
            cout << a[i];
            if (i != r) cout << "->";
        }
    };

    function<void(int,int)> print_right = [&](int l, int r) {
        if (l == r) {
            cout << a[l];
            return;
        }
        cout << "(";
        cout << a[l] << "->";
        print_right(l+1, r);
        cout << ")";
    };

    if (split == 1) {
        // left_expr is a_0 only
        cout << a[0] << "->";
    } else {
        print_left(0, split-1);
        cout << "->";
    }
    print_right(split, n-1);
    cout << "\n";

    return 0;
}

