#include <iostream>
using namespace std;

int main() {
    long long k;
    long long a, b;
    cin >> k >> a >> b;

    auto countDiv = [&](long long x) -> long long {
        if (x < 0) {
            // For negative x, count how many multiples of k are <= x
            // Multiples of k are ... -2k, -k, 0, k, 2k, ...
            // For negative x, number of multiples <= x is floor(x/k)
            // But since k > 0, floor division works as:
            // For negative x, floor division in C++ truncates towards zero, so we adjust:
            return (x / k) - ((x % k) != 0 ? 1 : 0);
        } else {
            // For non-negative x, number of multiples <= x is floor(x/k)
            return x / k;
        }
    };

    // To handle negative numbers correctly, we can use the formula:
    // number of multiples in [a,b] = countDiv(b) - countDiv(a-1)
    // But since countDiv uses floor division, we need to be careful.

    // Actually, since k > 0, and division in C++ truncates towards zero,
    // we can use a simpler approach:
    // number of multiples <= x = floor(x/k)
    // For negative x, floor(x/k) = (x - (k-1)) / k if x < 0
    // But to avoid complexity, we can use a function that returns floor division.

    auto floorDiv = [](long long x, long long y) -> long long {
        if (y < 0) y = -y;
        if (x >= 0) return x / y;
        else return (x - y + 1) / y;
    };

    long long res = floorDiv(b, k) - floorDiv(a - 1, k);
    cout << res << "\n";

    return 0;
}

