#include <bits/stdc++.h>
using namespace std;

const int MOD = 1'000'000'007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, x, pos;
    cin >> n >> x >> pos;

    // Precompute factorials and inverse factorials for permutations counting
    vector<long long> fact(n + 1, 1), invfact(n + 1, 1);
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;

    auto modpow = [](long long a, long long b, int mod) {
        long long res = 1;
        while (b > 0) {
            if (b & 1) res = res * a % mod;
            a = a * a % mod;
            b >>= 1;
        }
        return res;
    };

    invfact[n] = modpow(fact[n], MOD - 2, MOD);
    for (int i = n - 1; i >= 0; i--) invfact[i] = invfact[i + 1] * (i + 1) % MOD;

    auto perm = [&](int n, int k) -> long long {
        if (k > n || k < 0) return 0;
        return fact[n] * invfact[n - k] % MOD;
    };

    int left = 0, right = n;
    int less = 0, greater = 0;

    // Simulate the binary search to count how many elements must be less than x and how many greater
    while (left < right) {
        int mid = (left + right) / 2;
        if (mid <= pos) {
            if (mid != pos) less++;
            left = mid + 1;
        } else {
            greater++;
            right = mid;
        }
    }

    // less elements must be < x
    // greater elements must be > x
    // x is fixed at pos

    if (less > x - 1 || greater > n - x) {
        cout << 0 << "\n";
        return 0;
    }

    // Choose which less elements go to less positions: from x-1 elements less than x, choose less
    // Arrange them in less positions: less!
    // Choose which greater elements go to greater positions: from n - x elements greater than x, choose greater
    // Arrange them in greater positions: greater!
    // Remaining elements fill the rest positions: (n - 1 - less - greater)!

    long long ans = 1;
    ans = ans * perm(x - 1, less) % MOD;
    ans = ans * fact[less] % MOD;
    ans = ans * perm(n - x, greater) % MOD;
    ans = ans * fact[greater] % MOD;
    ans = ans * fact[n - 1 - less - greater] % MOD;

    cout << ans << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    string s; cin >> s;
    int k; cin >> k;

    // Parse the input into pairs: letter + modifier (0:none, 1:?, 2:*)
    vector<pair<char,int>> v;
    for (int i = 0; i < (int)s.size(); i++) {
        if (i+1 < (int)s.size() && (s[i+1] == '?' || s[i+1] == '*')) {
            v.push_back({s[i], s[i+1] == '?' ? 1 : 2});
            i++;
        } else {
            v.push_back({s[i], 0});
        }
    }

    int n = (int)v.size();

    // Calculate min and max length possible
    int min_len = 0, max_len = 0;
    bool has_star = false;
    for (auto &p : v) {
        if (p.second == 0) {
            min_len++;
            max_len++;
        } else if (p.second == 1) {
            // candy cane: letter can be removed or kept
            // min: 0, max: 1
            // min_len += 0
            max_len += 1;
        } else {
            // snowflake: letter can be removed, kept, or repeated many times
            has_star = true;
            // min: 0, max: infinite (but limited by k)
            // min_len += 0
            max_len = 1000000; // large number to represent infinity
        }
    }

    if (k < min_len) {
        cout << "Impossible\n";
        return 0;
    }
    if (!has_star && k > max_len) {
        cout << "Impossible\n";
        return 0;
    }

    // We will build the answer greedily:
    // Start with min_len letters (counting only letters without modifiers and letters with modifiers counted as 0)
    // Then add letters from candy canes and snowflakes to reach length k

    // First, count how many letters we have if we remove all optional letters (those with ? or * modifiers)
    int base_len = 0;
    for (auto &p : v) {
        if (p.second == 0) base_len++;
    }

    // Count how many letters with ? and * modifiers
    int q_count = 0;
    int star_count = 0;
    for (auto &p : v) {
        if (p.second == 1) q_count++;
        else if (p.second == 2) star_count++;
    }

    // The minimal length is base_len (all mandatory letters)
    // The maximal length is base_len + q_count (if no star) or infinite if star_count > 0

    // We want to reach length k
    // We can add letters from ? (each can add 0 or 1)
    // and from * (each can add 0 or many)

    // Let's try to assign how many times each letter is repeated:
    // For letters without modifier: count = 1
    // For letters with ?: count = 0 or 1
    // For letters with *: count = 0 or many

    // We want sum of counts = k

    // Start with counts:
    vector<int> counts(n, 1);
    for (int i = 0; i < n; i++) {
        if (v[i].second == 1 || v[i].second == 2) counts[i] = 0;
    }

    int current_len = base_len; // sum of counts

    // We need to increase current_len to k

    int need = k - current_len;

    // First, try to add 1 to each ? letter (max 1 per ?)
    for (int i = 0; i < n && need > 0; i++) {
        if (v[i].second == 1) {
            counts[i] = 1;
            need--;
        }
    }

    // If still need > 0 and we have star(s), add the rest to one star letter
    if (need > 0) {
        if (star_count == 0) {
            // no star to add more letters, impossible
            cout << "Impossible\n";
            return 0;
        }
        // add all remaining need to the first star letter
        for (int i = 0; i < n; i++) {
            if (v[i].second == 2) {
                counts[i] = need + 1; // +1 because minimal count is 0, but we already set counts[i]=0, so add need+1
                need = 0;
                break;
            }
        }
    }

    if (need != 0) {
        cout << "Impossible\n";
        return 0;
    }

    // Build the answer
    string ans;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < counts[i]; j++) {
            ans.push_back(v[i].first);
        }
    }

    if ((int)ans.size() != k) {
        cout << "Impossible\n";
        return 0;
    }

    cout << ans << "\n";

    return 0;
}

#include <iostream>
