int main() {
    long long x;
    cin >> x;

    // Image rotation angle is -x (counter-clockwise rotation of image)
    // We want to apply k * 90 degrees clockwise turns to minimize deviation from vertical.
    // Total rotation after k turns: r = -x + 90*k (mod 360)
    // Deviation from vertical = min(r mod 360, 360 - (r mod 360))

    // We'll try k = 0..3 and pick the minimal deviation and minimal k.

    int best_k = 0;
    int best_dev = 360;

    for (int k = 0; k < 4; ++k) {
        long long r = (-x + 90LL * k) % 360;
        if (r < 0) r += 360;
        int dev = (r <= 180) ? r : 360 - r;
        if (dev < best_dev) {
            best_dev = dev;
            best_k = k;
        }
    }

    cout << best_k << "\n";

    return 0;
}

