int main() {
    long long a, b, c;
    long long x, y, z;
    cin >> a >> b >> c;
    cin >> x >> y >> z;

    // Check if initial spheres are already enough
    if (a >= x && b >= y && c >= z) {
        cout << "Yes\n";
        return 0;
    }

    // Calculate deficits
    long long dx = max(0LL, x - a);
    long long dy = max(0LL, y - b);
    long long dz = max(0LL, z - c);

    // Calculate surpluses
    long long sa = max(0LL, a - x);
    long long sb = max(0LL, b - y);
    long long sc = max(0LL, c - z);

    // Each move consumes 2 spheres of the same color to produce 1 sphere of another color
    // So surplus spheres can be converted into other colors at a rate of floor(surplus/2)
    long long total_surplus_pairs = (sa / 2) + (sb / 2) + (sc / 2);
    long long total_deficit = dx + dy + dz;

    if (total_surplus_pairs >= total_deficit) {
        cout << "Yes\n";
    } else {
        cout << "No\n";
    }

    return 0;
}

