#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;

    // We try all possible intervals [l, r] that include k
    // Nastya must clear all manholes in [l, r]
    // The cost is:
    // - Move from k to l or r (whichever is closer)
    // - Throw stones to clear manholes outside [l, r]
    // - Open all manholes in [l, r]
    // The minimal cost is the minimal over all intervals containing k

    long long ans = 1e15;

    for (int l = 1; l <= k; ++l) {
        for (int r = k; r <= n; ++r) {
            // Number of manholes outside [l, r]
            int left_out = l - 1;
            int right_out = n - r;

            // Moves to clear stones outside [l, r]:
            // For each manhole outside, we need to throw its stone to inside [l, r]
            // Each stone throw costs 1 move
            long long stones_moves = left_out + right_out;

            // Moves to open all manholes in [l, r]: one move per manhole (open)
            long long open_moves = r - l + 1;

            // Moves to move from k to l or r (whichever is closer)
            long long move_to_edge = min(abs(k - l), abs(k - r));

            // Moves to traverse from one edge to the other to open all manholes
            long long traverse = r - l;

            // Total moves:
            // stones_moves (throw stones from outside to inside)
            // + open_moves (open all manholes inside)
            // + move_to_edge (go from k to start of interval)
            // + traverse (go from start to end of interval to open all)
            long long total = stones_moves + open_moves + move_to_edge + traverse;

            ans = min(ans, total);
        }
    }

    cout << ans << "\n";

    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;
    vector<int> a(k);
    int total = 0;
    for (int i = 0; i < k; i++) {
        cin >> a[i];
        total += a[i];
    }

    // Total seats
    int seats = 8 * n;

    // Count how many groups have odd number of soldiers
    int oddCount = 0;
    for (int i = 0; i < k; i++) {
        if (a[i] % 2 == 1) oddCount++;
    }

    // Count how many pairs of seats are available for single soldiers
    // The pairs are: (1,2), (3,4), (4,5), (5,6), (7,8)
    // But note that (4,5) and (5,6) overlap at seat 5, so we consider the pairs as:
    // pairs: (1,2), (3,4), (5,6), (7,8) and the "middle" pair (4,5) overlaps with (3,4) and (5,6)
    // The problem states neighbors are {1,2}, {3,4}, {4,5}, {5,6}, {7,8}
    // To avoid different groups sitting next to each other, groups with odd soldiers must be placed in single seats that are not neighbors to other groups.
    // The best way is to count how many single seats are available that are not neighbors to other groups.
    // The problem solution approach:
    // - Each pair of seats can hold 2 soldiers from the same group.
    // - Odd soldiers require a single seat.
    // - Single seats are those that are not part of pairs or leftover seats.
    // The problem solution from editorial:
    // - Count how many pairs of seats are available: total pairs = 4*n (since each row has 4 pairs: (1,2), (3,4), (5,6), (7,8))
    // - Count how many single seats are available: total singles = n (seat 4 or 5 can be used as single seats)
    // But the problem states neighbors are {1,2}, {3,4}, {4,5}, {5,6}, {7,8}
    // So seats 4 and 5 are neighbors to two pairs each.
    // The editorial approach is:
    // - Count how many pairs of seats are available: pairs = 4*n
    // - Count how many single seats are available: singles = n (because seats 4 and 5 overlap, but total single seats available is n)
    // - For each group:
    //   - Use pairs to seat floor(a[i]/2) soldiers
    //   - Use singles to seat the leftover 1 soldier if a[i] is odd
    // If singles < oddCount, print NO
    // Else print YES

    int pairs = 4 * n;
    int singles = 0;

    // Count how many single seats are available
    // Each row has 2 seats (4 and 5) that are neighbors to two pairs, so they can be used as single seats
    // But since seats 4 and 5 are neighbors, only one of them can be used as single seat per row to avoid neighbors from different groups
    // So singles = n (one single seat per row)
    singles = n;

    // Calculate how many pairs are needed
    int neededPairs = 0;
    for (int i = 0; i < k; i++) {
        neededPairs += a[i] / 2;
    }

    if (neededPairs > pairs) {
        cout << "NO\n";
        return 0;
    }

    if (oddCount > singles) {
        cout << "NO\n";
        return 0;
    }

    cout << "YES\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <climits>

using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for(int &x : a) cin >> x;

    int best_t = 1;
    int min_cost = INT_MAX;

    // Since a_i <= 100, and t can be any positive integer,
    // we can try t from 1 to 102 (to cover a_i+1)
    for(int t = 1; t <= 102; ++t) {
        int cost = 0;
        for(int x : a) {
            // For each stick, we want to change it to a length in {t-1, t, t+1}
            // that minimizes |x - new_length|
            // new_length must be positive
            int best_local = INT_MAX;
            for(int candidate = t-1; candidate <= t+1; ++candidate) {
                if(candidate > 0) {
                    int cur_cost = abs(x - candidate);
                    if(cur_cost < best_local) best_local = cur_cost;
                }
            }
            cost += best_local;
        }
        if(cost < min_cost) {
            min_cost = cost;
            best_t = t;
        }
    }

    cout << best_t << " " << min_cost << "\n";

    return 0;
}
